const e="programminglessondesigner",s="ProgrammingLessonDesigner",t={vueRoutes:"src/router/index.ts"},a=[{id:"start",title:{en:"Getting started",fa:"شروع"}},{id:"lessons",title:{en:"How a lesson is made",fa:"یک درس چطور ساخته می‌شود"}},{id:"examples",title:{en:"The tested examples",fa:"مثال‌های تست‌شده"}},{id:"reading",title:{en:"Reading, printing, reviewing",fa:"خواندن، چاپ، مرور"}},{id:"projects",title:{en:"The Projects tab",fa:"تب پروژه‌ها"}},{id:"styling",title:{en:"Colours that stay readable",fa:"رنگ‌هایی که خوانا می‌مانند"}},{id:"deploy",title:{en:"Build and deploy",fa:"build و استقرار"}}],o=[{id:"run",group:"start",title:{en:"Run it: the commands",fa:"اجرا: دستورها"},files:["README.md","package.json","vite.config.ts"],en:[{id:"commands",h:"One Vue app, a handful of scripts",p:["The site is a Vue 3 app built by Vite, with no server of its own: every lesson, topic and snapshot is a JSON file bundled at build time. `npm run dev` serves it on port 5173, `npm run build` type-checks with `vue-tsc` and writes `dist/`.","`npm run check` is the one that matters before a push: it validates the lessons, the Projects pages, the system map and the code snapshots against the real repos. `npm run map` and `npm run code` regenerate the last two.","`check` is four scripts in a row, and the first failure stops the chain: the lessons, the Projects pages, the map against Control Panel, and the snapshots against their repos. The runtime dependencies are only Vue, Vue Router, highlight.js and two font packages; everything else (Sass, stylelint, Playwright for the PDFs) is needed only to build or check."],examples:["scripts"]},{id:"base",h:"Built for two addresses",p:["The same build serves from the root of code.arashkeshtgar.ca and from `/ProgrammingLessonDesigner/` on GitHub Pages. Nothing in the code names either: the CI passes `--base` on the command line, and the HTML uses `%BASE_URL%` for the manifest and icon.","This matters because GitHub Pages serves the site under the repository's name, while the VPS serves it at `/`: a path written into the code would break one of the two. The service worker is registered at `BASE_URL` as well, and the manifest's start address is `.`, so an installed app opens wherever it was installed from."],examples:["vite"]}],fa:[{id:"commands",h:"یک اپ Vue و چند اسکریپت",p:["سایت یک اپ Vue 3 است که Vite آن را build می‌کند و سرور مخصوص خودش را ندارد: هر درس، هر تاپیک و هر snapshot یک فایل JSON است که موقع build داخل bundle می‌رود. `npm run dev` آن را روی پورت 5173 بالا می‌آورد و `npm run build` با `vue-tsc` نوع‌ها را چک می‌کند و `dist/` را می‌نویسد.","دستوری که قبل از هر push مهم است `npm run check` است: درس‌ها، صفحه‌های پروژه‌ها، نقشه‌ی سیستم و snapshotهای کد را با repoهای واقعی می‌سنجد. `npm run map` و `npm run code` دو تای آخر را از نو می‌سازند.","`check` چهار اسکریپت پشت سر هم است، و اولین شکست زنجیره را متوقف می‌کند: درس‌ها، صفحه‌های Projects، نقشه در برابر Control Panel، و snapshotها در برابر repoهایشان. وابستگی‌های زمان اجرا فقط Vue، Vue Router، highlight.js و دو بسته‌ی فونت‌اند؛ بقیه (Sass، stylelint، Playwright برای PDFها) فقط برای build یا چک لازم‌اند."],examples:["scripts"]},{id:"base",h:"build برای دو آدرس",p:["همین build هم از ریشه‌ی code.arashkeshtgar.ca سرو می‌شود و هم از `/ProgrammingLessonDesigner/` روی GitHub Pages. هیچ‌جای کد اسم هیچ‌کدام را نمی‌آورد: CI در خط فرمان `--base` می‌دهد و HTML برای manifest و آیکون از `%BASE_URL%` استفاده می‌کند.","این مهم است چون GitHub Pages سایت را زیر اسم repository سرو می‌کند، در حالی که VPS آن را روی `/` سرو می‌کند: مسیری که در کد نوشته شود یکی از این دو را خراب می‌کرد. service worker هم روی `BASE_URL` ثبت می‌شود، و آدرس شروع manifest برابر `.` است، پس اپ نصب‌شده از هر جا که نصب شده باز می‌شود."],examples:["vite"]}],examples:{scripts:{title:{en:"The scripts",fa:"اسکریپت‌ها"},lang:"json",file:"package.json",from:'"scripts": {',to:'"code": "node scripts/project-code.mjs"'},vite:{title:{en:"No base in the config",fa:"بدون base در تنظیمات"},lang:"typescript",file:"vite.config.ts",from:"// For a GitHub Pages build",lines:6}},quiz:[{q:{en:"Why can the site run with no server of its own?",fa:"چرا سایت می‌تواند بدون هیچ سرور خودش اجرا شود؟"},options:{en:["It fetches the lessons from GitHub at run time","Every lesson, topic and snapshot is a JSON file bundled at build time","The service worker generates the pages"],fa:["درس‌ها را موقع اجرا از GitHub می‌گیرد","هر درس، topic و snapshot یک فایل JSON است که موقع build باندل می‌شود","service worker صفحه‌ها را می‌سازد"]},answer:1,why:{en:"`dist/` is static files only, which is why GitHub Pages and a plain nginx can both serve it.",fa:"`dist/` فقط فایل ایستاست، به همین دلیل GitHub Pages و یک nginx ساده هر دو می‌توانند سروش کنند."}},{q:{en:"How does the same code serve from `/` and from `/ProgrammingLessonDesigner/`?",fa:"یک کد چطور هم از `/` و هم از `/ProgrammingLessonDesigner/` سرو می‌شود؟"},options:{en:["The base is passed with `--base` at build time, and the HTML uses `%BASE_URL%`","A redirect on GitHub Pages","Two copies of `vite.config.ts`"],fa:["base موقع build با `--base` داده می‌شود، و HTML از `%BASE_URL%` استفاده می‌کند","یک redirect روی GitHub Pages","دو نسخه از `vite.config.ts`"]},answer:0,why:{en:"Nothing in the source names either address, so neither build can drift.",fa:"هیچ جای کد اسم هیچ کدام از دو آدرس را نمی‌آورد، پس هیچ کدام از دو build از دیگری جدا نمی‌افتد."}},{q:{en:"A lesson names a region that no longer exists in its `examples/` file. Which command stops you before the push?",fa:"یک درس regionی را نام می‌برد که دیگر در فایل `examples/` آن نیست. کدام دستور پیش از push جلویتان را می‌گیرد؟"},options:{en:["`npm run dev`","`npm run build`","`npm run check`, whose first script checks every sample's file and region"],fa:["`npm run dev`","`npm run build`","`npm run check`، که اولین اسکریپتش فایل و region هر sample را چک می‌کند"]},answer:2,why:{en:'The build would succeed and the page would show a "missing region" comment; the check refuses it.',fa:"build موفق می‌شد و صفحه کامنت «missing region» نشان می‌داد؛ check آن را رد می‌کند."}}]},{id:"shell",group:"start",title:{en:"Three tabs and the router",fa:"سه تب و router"},files:["src/main.ts","src/App.vue","src/router/index.ts"],en:[{id:"tabs",h:"Lessons, review, projects",p:["The top bar has three tabs: the lessons (and their booklets), the review cards, and the Projects tab. The page is right-to-left Persian; code blocks and the English Projects pages switch direction on their own element.","Which tab is lit comes from the route's name: `review` and `projects` light their own tab, and every other page (a lesson, a booklet) belongs to the lessons. After each navigation the router also sets the window's title from the page: the lesson's English name, the booklet's, or Review."],examples:["tabs","title"]},{id:"routes",h:"Hash history",p:["Addresses are `#/lesson/l002`, `#/projects/fa/labflow/run` and so on. A hash route needs no rewrite rule on the server, so a deep link works on GitHub Pages and behind the VPS's plain nginx alike. The booklet, review and Projects views load on demand, so the lesson list opens without them.","`/projects` on its own redirects to the language the reader last chose, which is kept in the browser.","Scrolling follows the same idea: a new page starts at the top, but when only the parameters after the path change, the page stays where it was. When storage is blocked, the saved language falls back to Persian instead of failing."],examples:["router"],data:{kind:"routes"}}],fa:[{id:"tabs",h:"درس‌ها، مرور، پروژه‌ها",p:["نوار بالا سه تب دارد: درس‌ها (و جزوه‌هایشان)، کارت‌های مرور، و تب پروژه‌ها. صفحه فارسی و راست‌به‌چپ است؛ بلوک‌های کد و صفحه‌های انگلیسی تب پروژه‌ها جهت را روی عنصر خودشان عوض می‌کنند.","این‌که کدام تب روشن باشد از اسم route می‌آید: `review` و `projects` تب خودشان را روشن می‌کنند، و هر صفحه‌ی دیگری (یک درس، یک جزوه) مال درس‌هاست. بعد از هر جابه‌جایی router عنوان پنجره را هم از روی صفحه می‌گذارد: اسم انگلیسی درس، اسم جزوه، یا Review."],examples:["tabs","title"]},{id:"routes",h:"hash history",p:["آدرس‌ها مثل `#/lesson/l002` و `#/projects/fa/labflow/run` هستند. route با hash روی سرور هیچ قاعده‌ی rewrite نمی‌خواهد، پس لینک مستقیم هم روی GitHub Pages کار می‌کند و هم پشت nginx ساده‌ی VPS. صفحه‌های جزوه، مرور و پروژه‌ها فقط وقتی لازم شوند بار می‌شوند، پس فهرست درس‌ها بدون آن‌ها باز می‌شود.","`/projects` به‌تنهایی به زبانی می‌رود که خواننده آخرین بار انتخاب کرده و در مرورگر نگه داشته شده.","اسکرول هم از همین فکر پیروی می‌کند: صفحه‌ی تازه از بالا شروع می‌شود، ولی وقتی فقط چیزی بعد از path عوض شود، صفحه همان‌جا که بود می‌ماند. وقتی storage بسته باشد، زبان ذخیره‌شده به جای شکست خوردن به فارسی برمی‌گردد."],examples:["router"],data:{kind:"routes"}}],examples:{tabs:{title:{en:"The top bar",fa:"نوار بالا"},lang:"xml",file:"src/App.vue",from:'<nav class="topbar">',to:"</nav>"},router:{title:{en:"The routes",fa:"routeها"},lang:"typescript",file:"src/router/index.ts",from:"// Hash history keeps deep links working",lines:14},title:{title:{en:"The window's title, per page",fa:"عنوان پنجره، برای هر صفحه"},lang:"typescript",file:"src/router/index.ts",from:"router.afterEach((to) => {",lines:9}},quiz:[{q:{en:"Why do the addresses use a hash (`#/lesson/l002`) instead of plain paths?",fa:"چرا آدرس‌ها به جای path ساده از hash استفاده می‌کنند (`#/lesson/l002`)؟"},options:{en:["The server only ever sees `/`, so a deep link works with no rewrite rule on GitHub Pages or nginx","Hash routes load faster","Vue Router supports nothing else"],fa:["سرور همیشه فقط `/` را می‌بیند، پس یک deep link بدون هیچ قانون rewrite روی GitHub Pages یا nginx کار می‌کند","routeهای hash سریع‌تر بار می‌شوند","Vue Router چیز دیگری پشتیبانی نمی‌کند"]},answer:0,why:{en:"The part after `#` never reaches the server, so it can't answer 404 for it.",fa:"بخش بعد از `#` هیچ‌وقت به سرور نمی‌رسد، پس سرور نمی‌تواند برایش 404 بدهد."}},{q:{en:"Why are the booklet, review and Projects views loaded on demand?",fa:"چرا viewهای جزوه، مرور و Projects در صورت نیاز بار می‌شوند؟"},options:{en:["They need a server","So the lesson list opens without downloading them","They change too often to bundle"],fa:["سرور لازم دارند","تا فهرست درس‌ها بدون دانلود آن‌ها باز شود","زیادی عوض می‌شوند که باندل شوند"]},answer:1,why:{en:"Their routes use `() => import(...)`, so Vite puts each in its own chunk.",fa:"routeهایشان از `() => import(...)` استفاده می‌کنند، پس Vite هر کدام را در chunk خودش می‌گذارد."}},{q:{en:"A reader opens `#/projects` in a private window where storage is blocked. Where do they land?",fa:"خواننده‌ای `#/projects` را در پنجره‌ی خصوصی‌ای که storage در آن بسته است باز می‌کند. کجا می‌رسد؟"},options:{en:["An error page","The English pages","The Persian pages, the default when no language can be read"],fa:["یک صفحه‌ی خطا","صفحه‌های انگلیسی","صفحه‌های فارسی، پیش‌فرض وقتی هیچ زبانی خوانده نشود"]},answer:2,why:{en:"`savedLang` catches the storage error and returns `fa`.",fa:"`savedLang` خطای storage را می‌گیرد و `fa` برمی‌گرداند."}}]},{id:"shape",group:"lessons",title:{en:"The shape of a lesson",fa:"شکل یک درس"},files:["src/types/lesson.ts","src/lib/lessons.ts","src/lib/booklets.ts"],en:[{id:"order",h:"One JSON file, always in the same order",p:["Every lesson is one file in `src/data/lessons/` and reads the same way: what you will be able to do, the real scenario it comes from, the concepts, a comparison table, the code, the common mistakes, where the code lives in the real projects, exercises, and one sentence to say in an interview.","The file name's letter is its booklet (`l` backend, `f` frontend, `d` Docker, `o` ops); there are 27 lessons in four booklets. Lessons are sorted by booklet, then by their number.","The fixed order is what lets one file serve three readers: the lesson page, the printed booklet, and the review cards, which are cut from the comparison rows, the mistakes and the exercises. The lesson check refuses a file with any of these fields missing or empty, so no lesson can quietly skip its mistakes or exercises. Each booklet numbers its lessons from 1, which is why the sort needs the booklet first."],examples:["lesson","sort"]},{id:"compare",h:"One concept, several languages",p:["A comparison row names a concept, how each language does it, and one line on what really differs. C# is the language the reader already knows and its column is highlighted; a lesson can name another (`known`) and its own columns (`langs`), as the frontend and ops lessons do."],examples:["compare"]}],fa:[{id:"order",h:"یک فایل JSON، همیشه به یک ترتیب",p:["هر درس یک فایل در `src/data/lessons/` است و همیشه به یک شکل خوانده می‌شود: بعد از درس چه کاری از تو برمی‌آید، سناریوی واقعی‌ای که درس از آن آمده، مفهوم‌ها، جدول مقایسه، کد، اشتباه‌های رایج، جای این کد در پروژه‌های واقعی، تمرین‌ها، و یک جمله برای مصاحبه.","حرف اول اسم فایل جزوه‌اش است (`l` بک‌اند، `f` فرانت‌اند، `d` Docker، `o` عملیات)؛ ۲۷ درس در چهار جزوه. درس‌ها اول بر اساس جزوه و بعد بر اساس شماره‌شان مرتب می‌شوند.","ترتیب ثابت همان چیزی است که یک فایل را برای سه خواننده کافی می‌کند: صفحه‌ی درس، جزوه‌ی چاپی، و کارت‌های مرور، که از ردیف‌های مقایسه، اشتباه‌ها و تمرین‌ها بریده می‌شوند. check درس‌ها فایلی را که هر کدام از این فیلدها را نداشته یا خالی داشته باشد رد می‌کند، پس هیچ درسی نمی‌تواند بی‌صدا اشتباه‌ها یا تمرین‌هایش را جا بیندازد. هر جزوه درس‌هایش را از ۱ شماره می‌زند، به همین دلیل مرتب‌سازی اول جزوه را لازم دارد."],examples:["lesson","sort"]},{id:"compare",h:"یک مفهوم، چند زبان",p:["هر ردیف مقایسه یک مفهوم را نام می‌برد، این‌که هر زبان چطور انجامش می‌دهد، و یک خط درباره‌ی تفاوت واقعی. C# زبانی است که خواننده از قبل بلد است و ستونش برجسته می‌شود؛ هر درس می‌تواند زبان دیگری (`known`) و ستون‌های خودش (`langs`) را بگوید، همان‌طور که درس‌های فرانت‌اند و عملیات می‌گویند."],examples:["compare"]}],examples:{lesson:{title:{en:"A lesson",fa:"یک درس"},lang:"typescript",file:"src/types/lesson.ts",from:"export interface Lesson {",lines:23},compare:{title:{en:"A comparison row",fa:"یک ردیف مقایسه"},lang:"typescript",file:"src/types/lesson.ts",from:"// One concept, several languages.",lines:2},sort:{title:{en:"Booklet first, then number",fa:"اول جزوه، بعد شماره"},lang:"typescript",file:"src/lib/lessons.ts",from:"// Booklet order first",lines:5}},quiz:[{q:{en:"Why does sorting by lesson number alone not work?",fa:"چرا مرتب‌سازی فقط با شماره‌ی درس کار نمی‌کند؟"},options:{en:["Numbers are strings","Each booklet numbers its lessons from 1, so the backend's lesson 1 and the ops lesson 1 would sit together","Vite loads the files in random order"],fa:["شماره‌ها رشته‌اند","هر جزوه درس‌هایش را از ۱ شماره می‌زند، پس درس ۱ بک‌اند و درس ۱ ops کنار هم می‌نشستند","Vite فایل‌ها را به ترتیب تصادفی بار می‌کند"]},answer:1,why:{en:"The sort compares the booklet's position in `BOOKLETS` first, then `n`.",fa:"مرتب‌سازی اول جای جزوه در `BOOKLETS` را مقایسه می‌کند، بعد `n` را."}},{q:{en:"A frontend lesson compares Blazor, Angular, React and Vue. How does it say so?",fa:"یک درس فرانت‌اند Blazor، Angular، React و Vue را مقایسه می‌کند. این را چطور می‌گوید؟"},options:{en:["With `langs` for its columns, and `known` for the column the reader already knows","By its file name's letter alone","It can't: every lesson compares the four backend languages"],fa:["با `langs` برای ستون‌هایش، و `known` برای ستونی که خواننده از قبل می‌شناسد","فقط با حرف اول اسم فایلش","نمی‌تواند: هر درس چهار زبان بک‌اند را مقایسه می‌کند"]},answer:0,why:{en:"Both are optional and default to the four backend languages and C#.",fa:"هر دو اختیاری‌اند و پیش‌فرضشان چهار زبان بک‌اند و C# است."}}]},{id:"samples",group:"lessons",title:{en:"Code samples: tested, real, port",fa:"نمونه‌کدها: تست‌شده، واقعی، ترجمه"},files:["src/types/lesson.ts","src/lib/code.ts","src/data/lessons/o004-deploy.json"],en:[{id:"origin",h:"Where a sample comes from",p:["A sample is one of three kinds, and the page says which. `tested` points at a file under `examples/` that CI compiles and tests; `real` is code shortened from one of the portfolio's projects; `port` was written for the lesson and never run, and is avoided (only the Azure Pipelines column uses it, since there is no runner for it here).","Samples with the same `group` become one block with a tab per language."],examples:["sample","json"]},{id:"region",h:"Regions, not line numbers",p:["A tested sample names a region: the lines between `#region <name>` and `#endregion`, in whatever comment syntax the language has (`//`, `#`, `<!-- -->`). The page reads the file itself, bundled raw by Vite, so what the reader sees is exactly what CI ran, and an edit above the region does not move it.","Inline `code` wins over a file, which is how a `real` sample carries its shortened quote. The region's lines are dedented, so a region inside a class doesn't arrive indented. The highlighting language comes from the file's extension when there is one, else from the tab, since a Vue tab may hold TypeScript or a template. A file or region that is missing shows as a comment in the block instead of breaking the page, but the lesson check refuses it first."],examples:["extract"]}],fa:[{id:"origin",h:"نمونه از کجا آمده",p:["هر نمونه یکی از سه نوع است و صفحه می‌گوید کدام. `tested` به فایلی زیر `examples/` اشاره می‌کند که CI آن را کامپایل و تست می‌کند؛ `real` کدی است که از یکی از پروژه‌های پورتفولیو کوتاه شده؛ `port` برای درس نوشته شده و هیچ‌وقت اجرا نشده، و از آن پرهیز می‌شود (فقط ستون Azure Pipelines از آن استفاده می‌کند، چون این‌جا runnerی برایش نیست).","نمونه‌هایی که `group` یکسان دارند یک بلوک می‌شوند با یک تب برای هر زبان."],examples:["sample","json"]},{id:"region",h:"region، نه شماره‌ی خط",p:["نمونه‌ی تست‌شده یک region را نام می‌برد: خط‌های بین `#region <name>` و `#endregion`، با هر نحو توضیحی که آن زبان دارد (`//`، `#`، `<!-- -->`). صفحه خود فایل را می‌خواند که Vite خام داخل bundle گذاشته، پس خواننده دقیقاً همان چیزی را می‌بیند که CI اجرا کرده، و ویرایش بالای region آن را جابه‌جا نمی‌کند.","`code` درون‌خطی بر فایل برنده است، و یک sample از نوع `real` نقل کوتاه‌شده‌اش را همین‌طور حمل می‌کند. سطرهای region تورفتگی‌شان برداشته می‌شود، پس regionی که داخل یک کلاس است با تورفتگی نمی‌رسد. زبان رنگ‌آمیزی، وقتی فایلی باشد، از پسوند فایل می‌آید و وگرنه از تب، چون تب Vue ممکن است TypeScript یا template داشته باشد. فایل یا regionی که نباشد به جای خراب کردن صفحه به‌صورت یک کامنت در بلوک دیده می‌شود، ولی check درس‌ها پیش‌تر ردش می‌کند."],examples:["extract"]}],examples:{sample:{title:{en:"A code sample",fa:"یک نمونه‌کد"},lang:"typescript",file:"src/types/lesson.ts",from:"// Samples sharing a `group`",lines:15},json:{title:{en:"One block, three languages",fa:"یک بلوک، سه زبان"},lang:"json",file:"src/data/lessons/o004-deploy.json",from:'{ "group": "lock", "lang": "bash"',lines:3},extract:{title:{en:"Cutting a region out",fa:"بریدن یک region"},lang:"typescript",file:"src/lib/code.ts",from:'// The lines between "#region <name>"',lines:22}},quiz:[{q:{en:"Why do tested samples name a region rather than a range of line numbers?",fa:"چرا sampleهای تست‌شده به جای بازه‌ی شماره‌ی سطر یک region را نام می‌برند؟"},options:{en:["Line numbers can't be read at build time","Regions are faster to find","An edit above the region would move line numbers, but not the markers"],fa:["شماره‌ی سطرها موقع build خواندنی نیستند","regionها سریع‌تر پیدا می‌شوند","ویرایشی بالای region شماره‌ی سطرها را جابه‌جا می‌کرد، ولی نشانگرها را نه"]},answer:2,why:{en:"The markers travel with the code, so the page keeps showing the right lines.",fa:"نشانگرها همراه کد جابه‌جا می‌شوند، پس صفحه همچنان سطرهای درست را نشان می‌دهد."}},{q:{en:"What does the label `tested` on a sample promise?",fa:"برچسب `tested` روی یک sample چه قولی می‌دهد؟"},options:{en:["The code was reviewed by hand","The file under `examples/` is compiled and tested by CI, and the page shows exactly that file","It was copied from a real project"],fa:["کد دستی بازبینی شده","فایل زیر `examples/` را CI کامپایل و تست می‌کند، و صفحه دقیقاً همان فایل را نشان می‌دهد","از یک پروژه‌ی واقعی کپی شده"]},answer:1,why:{en:"The page reads the file raw from the bundle, so nothing is copied by hand between test and page.",fa:"صفحه فایل را خام از باندل می‌خواند، پس هیچ چیز دستی بین تست و صفحه کپی نمی‌شود."}},{q:{en:"Four samples share the `group` `lock`. How are they shown?",fa:"چهار sample در `group`‌ی `lock` مشترک‌اند. چطور نشان داده می‌شوند؟"},options:{en:["As one block with a tab per language","As four blocks one under the other on screen","Only the first is shown"],fa:["به‌صورت یک بلوک با یک تب برای هر زبان","به‌صورت چهار بلوک زیر هم روی صفحه","فقط اولی نشان داده می‌شود"]},answer:0,why:{en:"On screen they are tabs; only in a booklet are all languages shown one under the other.",fa:"روی صفحه تب‌اند؛ فقط در جزوه همه‌ی زبان‌ها زیر هم نشان داده می‌شوند."}}]},{id:"checks",group:"lessons",title:{en:"The lesson check",fa:"چک درس‌ها"},files:["scripts/check-lessons.mjs"],en:[{id:"langs",h:"Every language, every region",p:["`npm run check` starts with the lessons: every required field is there, ids are unique, every code group and every comparison row covers each of the lesson's languages, and every `examples/` file and region a sample names exists. A lesson with a missing Java tab does not build.","It also refuses a tab for a language the lesson doesn't list, and a sample with neither code nor a file. The check doesn't stop at the first problem: it collects them all, prints them together and exits with 1, so one run tells you everything to fix, and CI fails on the same output."],examples:["langs","fail"]},{id:"refs",h:"References into the real projects",p:["Each lesson ends with where its code lives in the portfolio, as `project/file:line`. Locally, where `D:/E/Projects` exists, the check opens each file and fails when it is gone or shorter than the line named. CI has no copy of the projects and skips this part.","The projects folder can be moved with `LESSON_REFS_ROOT`. Checking the length catches the common decay: a file in another repo is shortened, and a reference to its line 240 now points past its end."],examples:["refs"]}],fa:[{id:"langs",h:"همه‌ی زبان‌ها، همه‌ی regionها",p:["`npm run check` با درس‌ها شروع می‌کند: همه‌ی فیلدهای لازم هستند، idها تکراری نیستند، هر گروه کد و هر ردیف مقایسه همه‌ی زبان‌های درس را دارد، و هر فایل و region زیر `examples/` که نمونه‌ای نام برده وجود دارد. درسی که تب Java ندارد build نمی‌شود.","تبی برای زبانی که درس فهرستش نکرده، و sampleی که نه کد دارد نه فایل، هم رد می‌شوند. check در اولین مشکل نمی‌ایستد: همه را جمع می‌کند، با هم چاپ می‌کند و با کد 1 خارج می‌شود، پس یک اجرا همه‌ی چیزهایی را که باید درست شوند می‌گوید، و CI روی همان خروجی شکست می‌خورد."],examples:["langs","fail"]},{id:"refs",h:"ارجاع به پروژه‌های واقعی",p:["هر درس با جای کدش در پورتفولیو تمام می‌شود، به شکل `project/file:line`. روی PC، جایی که `D:/E/Projects` هست، چک هر فایل را باز می‌کند و اگر نباشد یا از خط گفته‌شده کوتاه‌تر باشد خطا می‌دهد. CI کپی پروژه‌ها را ندارد و از این بخش رد می‌شود.","پوشه‌ی پروژه‌ها را می‌شود با `LESSON_REFS_ROOT` جای دیگری گذاشت. چک طول همان فرسایش رایج را می‌گیرد: فایلی در repo دیگر کوتاه شده، و ارجاع به سطر ۲۴۰ آن حالا از انتهایش جلوتر است."],examples:["refs"]}],examples:{langs:{title:{en:"Groups and rows against the lesson's languages",fa:"گروه‌ها و ردیف‌ها در برابر زبان‌های درس"},lang:"javascript",file:"scripts/check-lessons.mjs",from:"const groups = {}",to:"for (const r of l.compare ?? [])"},refs:{title:{en:"A ref past the end of its file",fa:"ارجاعی بعد از انتهای فایل"},lang:"javascript",file:"scripts/check-lessons.mjs",from:"if (existsSync(refsRoot))",lines:10},fail:{title:{en:"Every problem, then exit 1",fa:"همه‌ی مشکلات، بعد خروج با 1"},lang:"javascript",file:"scripts/check-lessons.mjs",from:"if (problems.length) {",lines:5}},quiz:[{q:{en:"A lesson's code group has C#, TypeScript and Python tabs but no Java. What happens?",fa:"یک گروه کد در درسی تب C#، TypeScript و Python دارد ولی Java ندارد. چه می‌شود؟"},options:{en:["The page shows three tabs","`npm run check` fails: every group must cover each of the lesson's languages","Java is filled from the C# sample"],fa:["صفحه سه تب نشان می‌دهد","`npm run check` شکست می‌خورد: هر گروه باید همه‌ی زبان‌های درس را پوشش دهد","Java از روی sample‌ی C# پر می‌شود"]},answer:1,why:{en:"A group with `all` is exempt, since it is one sample for every language.",fa:"گروهی که `all` دارد معاف است، چون یک sample برای همه‌ی زبان‌هاست."}},{q:{en:"Why does CI skip the check of references into the real projects?",fa:"چرا CI چک ارجاع‌ها به پروژه‌های واقعی را رد می‌کند؟"},options:{en:["CI has no copy of the projects folder","The references are only comments","It is too slow"],fa:["CI هیچ نسخه‌ای از پوشه‌ی پروژه‌ها ندارد","ارجاع‌ها فقط کامنت‌اند","خیلی کند است"]},answer:0,why:{en:"It runs only when the folder exists, which is on the developer's machine.",fa:"فقط وقتی اجرا می‌شود که پوشه وجود داشته باشد، یعنی روی ماشین توسعه‌دهنده."}}]},{id:"backend",group:"examples",title:{en:"Four backends, one API",fa:"چهار بک‌اند، یک API"},files:["examples/backend/csharp/Portfolio/PortfolioApp.cs","examples/backend/python/portfolio/app.py","examples/backend/typescript/src/app.ts","examples/backend/java/src/main/java/portfolio/PortfolioController.java",".github/workflows/deploy-pages.yml"],en:[{id:"same",h:"The same service, written four times",p:["The backend lessons compare C#, TypeScript, Python and Java on one small service: `/status`, projects, sign-in with refresh tokens, roles, a webhook, an outbox, an LLM tool loop. ASP.NET Core Minimal API, Express, FastAPI and Spring Boot each implement the same endpoints with the same answers, so a comparison is between equals.","Each one builds its app in a factory that takes its dependencies as arguments, so the tests pass fakes and a real database alike.","The factories are `PortfolioApp.Build`, `createApp` and `create_app`: each takes the status queries, the project repository and the token service and returns an app that hasn't started. That is what makes the comparison fair, because each language's test can hand in the same kind of fake without a framework's container getting in the way."],examples:["cs","py"]},{id:"tests",h:"Tested in their own language",p:["`dotnet test`, `npm test`, `pytest` and `mvn test` run in CI, each with a real MongoDB for the lesson that needs one, around twenty tests per language. Only after all of them pass is the site published, which is what the “tested” label on a sample means."]},{id:"mongo",h:"One job per language",p:["Each language is its own CI job with its own MongoDB 7 as a service container on port 27017, found through `MONGO_URL`. The jobs run side by side, so a failing Java test names Java, and the TypeScript job also type-checks with `tsc --noEmit` before its tests."],examples:["job"]}],fa:[{id:"same",h:"یک سرویس، چهار بار نوشته‌شده",p:["درس‌های بک‌اند C#، TypeScript، Python و Java را روی یک سرویس کوچک مقایسه می‌کنند: `/status`، پروژه‌ها، ورود با refresh token، نقش‌ها، یک webhook، یک outbox، یک حلقه‌ی ابزار LLM. ASP.NET Core Minimal API، Express، FastAPI و Spring Boot هر کدام همان endpointها را با همان جواب‌ها پیاده می‌کنند، پس مقایسه بین هم‌ارزهاست.","هر کدام اپ را در یک factory می‌سازد که وابستگی‌هایش را به‌صورت آرگومان می‌گیرد، پس تست‌ها هم fake می‌دهند و هم دیتابیس واقعی.","factoryها `PortfolioApp.Build`، `createApp` و `create_app`اند: هر کدام queryهای وضعیت، repository پروژه‌ها و سرویس token را می‌گیرد و اپی برمی‌گرداند که هنوز شروع نشده. همین مقایسه را منصفانه می‌کند، چون تست هر زبان می‌تواند همان نوع fake را بدهد بی‌آن‌که container یک framework سر راه باشد."],examples:["cs","py"]},{id:"tests",h:"تست‌شده در زبان خودشان",p:["`dotnet test`، `npm test`، `pytest` و `mvn test` در CI اجرا می‌شوند، هر کدام با یک MongoDB واقعی برای درسی که لازمش دارد، حدود بیست تست برای هر زبان. سایت فقط وقتی منتشر می‌شود که همه‌شان پاس شوند؛ برچسب «تست‌شده» روی نمونه یعنی همین."]},{id:"mongo",h:"یک job برای هر زبان",p:["هر زبان job خودش را در CI دارد با MongoDB 7 خودش به‌صورت service container روی پورت 27017، که از راه `MONGO_URL` پیدا می‌شود. jobها کنار هم اجرا می‌شوند، پس تست شکست‌خورده‌ی Java اسم Java را می‌آورد، و job‌ی TypeScript پیش از تست‌هایش با `tsc --noEmit` نوع‌ها را هم چک می‌کند."],examples:["job"]}],examples:{cs:{title:{en:"C#: /status and a project by key",fa:"C#: ‏/status و یک پروژه با کلید"},lang:"csharp",file:"examples/backend/csharp/Portfolio/PortfolioApp.cs",from:'app.MapGet("/status"',to:'Results.NotFound(new { error = $"Unknown project: {key}" }));'},py:{title:{en:"Python: the same /status",fa:"Python: همان /status"},lang:"python",file:"examples/backend/python/portfolio/app.py",from:'@app.get("/status")',lines:10},job:{title:{en:"Python's job, with its own MongoDB",fa:"job‌ی Python، با MongoDB خودش"},lang:"yaml",file:".github/workflows/deploy-pages.yml",from:"python:",to:"MONGO_URL"}},quiz:[{q:{en:"Why does each backend build its app in a factory that takes its dependencies as arguments?",fa:"چرا هر بک‌اند اپش را در factoryی می‌سازد که وابستگی‌ها را به‌صورت آرگومان می‌گیرد؟"},options:{en:["It is required by every framework","So tests can pass fakes or a real database to the same code","So the app starts faster"],fa:["هر frameworkی آن را لازم دارد","تا تست‌ها بتوانند fake یا یک دیتابیس واقعی را به همان کد بدهند","تا اپ سریع‌تر شروع شود"]},answer:1,why:{en:"The app never reaches for its own dependencies, so swapping them needs no mocking library.",fa:"اپ هیچ‌وقت خودش سراغ وابستگی‌هایش نمی‌رود، پس عوض کردنشان به کتابخانه‌ی mock نیاز ندارد."}},{q:{en:"The Java tests fail but the other three pass. Is the site published?",fa:"تست‌های Java شکست می‌خورند ولی سه تای دیگر قبول می‌شوند. سایت منتشر می‌شود؟"},options:{en:["Yes, with Java hidden","Yes, the labels just say `port`","No: the deploy job needs every test job to pass"],fa:["بله، با Java پنهان","بله، فقط برچسب‌ها `port` می‌شوند","نه: job‌ی deploy قبول شدن همه‌ی jobهای تست را لازم دارد"]},answer:2,why:{en:'That is what the "tested" label means: nothing reaches the site unless every language passed.',fa:"معنای برچسب «tested» همین است: هیچ چیز به سایت نمی‌رسد مگر همه‌ی زبان‌ها قبول شده باشند."}}]},{id:"frontend",group:"examples",title:{en:"Frontend: Angular, React, Vue, Blazor",fa:"فرانت‌اند: Angular، React، Vue، Blazor"},files:["examples/frontend/web/package.json","examples/frontend/web/shared/api.ts","examples/frontend/web/test/api.test.ts","examples/frontend/web/vue/router.ts"],en:[{id:"shared",h:"One fetch wrapper under three frameworks",p:["The frontend lessons compare components, HTTP with token refresh, route guards and forms. Angular, React and Vue share one `shared/api.ts`: a fetch wrapper that refreshes an expired token once, however many requests got a 401 at the same time, then retries each of them. Its tests run on Node's own test runner, no browser needed.","The three frameworks are type-checked with `tsc` and `vue-tsc`; Blazor's components are tested with bUnit under `dotnet test`. Angular's templates are not compiled, and the README says so.","Why only one refresh: the server rotates refresh tokens, so two refreshes sent with the same token would race, and the loser would sign the user out. The wrapper keeps one promise for the refresh in flight, every 401 waits on it, and it is cleared when it settles. When the refresh itself fails, the tokens are cleared and the app is told the user is signed out. `npm test` runs the test file with `tsx --test`, Node's own test runner with TypeScript loaded, and a fake `fetch`."],examples:["refresh"]},{id:"guard",h:"A guard as data",p:["Vue's version of a route guard puts the role on the route as `meta` and checks it in one global `beforeEach`; returning a path redirects.","The role is declared on `RouteMeta`, so `meta.role` is typed. This example uses ordinary history, unlike the site itself; the guard works the same with either."],examples:["guard"]}],fa:[{id:"shared",h:"یک wrapper برای fetch زیر سه فریم‌ورک",p:["درس‌های فرانت‌اند کامپوننت‌ها، HTTP با تازه‌کردن token، guardهای route و فرم‌ها را مقایسه می‌کنند. Angular، React و Vue یک `shared/api.ts` مشترک دارند: wrapperی دور fetch که token منقضی را فقط یک بار تازه می‌کند، هر چند درخواست هم که هم‌زمان 401 گرفته باشند، و بعد هر کدام را دوباره می‌فرستد. تست‌هایش با test runner خود Node اجرا می‌شوند و مرورگر لازم ندارند.","نوع‌های سه فریم‌ورک با `tsc` و `vue-tsc` چک می‌شوند؛ کامپوننت‌های Blazor با bUnit زیر `dotnet test` تست می‌شوند. templateهای Angular کامپایل نمی‌شوند و README هم همین را می‌گوید.","چرا فقط یک refresh: سرور refresh tokenها را می‌چرخاند، پس دو refresh که با یک token فرستاده شوند با هم مسابقه می‌دادند، و بازنده کاربر را خارج می‌کرد. wrapper یک promise برای refresh در جریان نگه می‌دارد، هر 401 منتظر همان می‌ماند، و وقتی تمام شود پاک می‌شود. وقتی خود refresh شکست بخورد، tokenها پاک می‌شوند و به اپ گفته می‌شود کاربر خارج شده. `npm test` فایل تست را با `tsx --test` اجرا می‌کند، test runner خود Node با TypeScript بارشده، و یک `fetch` جعلی."],examples:["refresh"]},{id:"guard",h:"guard به شکل داده",p:["نسخه‌ی Vue از guard، نقش را به‌صورت `meta` روی route می‌گذارد و در یک `beforeEach` سراسری چکش می‌کند؛ برگرداندن یک مسیر یعنی redirect.","نقش روی `RouteMeta` تعریف شده، پس `meta.role` نوع دارد. این مثال، برخلاف خود سایت، از history معمولی استفاده می‌کند؛ guard با هر دو یکسان کار می‌کند."],examples:["guard"]}],examples:{refresh:{title:{en:"Two 401s, one refresh",fa:"دو 401، یک refresh"},lang:"typescript",file:"examples/frontend/web/test/api.test.ts",from:"it('refreshes once for parallel 401s",lines:19},guard:{title:{en:"The role on the route",fa:"نقش روی route"},lang:"typescript",file:"examples/frontend/web/vue/router.ts",from:"export const router = createRouter({",lines:13}},quiz:[{q:{en:"Three requests get a 401 at the same moment. How many refresh calls does the shared wrapper make?",fa:"سه درخواست هم‌زمان 401 می‌گیرند. wrapper مشترک چند call‌ی refresh می‌زند؟"},options:{en:["One, shared by all three, then each request is retried","Three, one per request","None: it signs the user out"],fa:["یکی، مشترک بین هر سه، بعد هر درخواست دوباره فرستاده می‌شود","سه تا، یکی برای هر درخواست","هیچ: کاربر را خارج می‌کند"]},answer:0,why:{en:"The refresh token rotates, so parallel refreshes with the same token would fight; one promise is shared.",fa:"refresh token می‌چرخد، پس refreshهای موازی با یک token با هم درگیر می‌شدند؛ یک promise به اشتراک گذاشته می‌شود."}},{q:{en:"In the Vue example, a user without the Admin role opens `/projects/new`. What happens?",fa:"در مثال Vue کاربری بدون نقش Admin مسیر `/projects/new` را باز می‌کند. چه می‌شود؟"},options:{en:["An error is thrown","The global `beforeEach` returns `/dashboard`, which redirects there","The form opens read-only"],fa:["یک خطا پرتاب می‌شود","`beforeEach` سراسری `/dashboard` را برمی‌گرداند، که به آن‌جا redirect می‌کند","فرم فقط‌خواندنی باز می‌شود"]},answer:1,why:{en:"Returning a path from a guard is a redirect; the role is read from the route's `meta`.",fa:"برگرداندن یک path از guard یعنی redirect؛ نقش از `meta` همان route خوانده می‌شود."}},{q:{en:"Which part of the frontend examples is honestly not checked by CI?",fa:"کدام بخش از مثال‌های فرانت‌اند صادقانه توسط CI چک نمی‌شود؟"},options:{en:["Vue's components","Blazor's components","Angular's templates, which are not compiled"],fa:["کامپوننت‌های Vue","کامپوننت‌های Blazor","templateهای Angular، که کامپایل نمی‌شوند"]},answer:2,why:{en:"The code is type-checked with `tsc`, but nothing compiles the templates, and the README says so.",fa:"کد با `tsc` چک نوع می‌شود، ولی هیچ چیز templateها را کامپایل نمی‌کند، و README همین را می‌گوید."}}]},{id:"docker",group:"examples",title:{en:"Docker: the four services together",fa:"Docker: چهار سرویس با هم"},files:["examples/docker/compose.yml",".github/workflows/deploy-pages.yml"],en:[{id:"compose",h:"No default secrets",p:["The Docker lessons package the same four backends. One compose file builds them with a MongoDB that publishes no port and sits on an `internal` network only the Python service joins. The secrets come from the environment, and `${VAR:?message}` stops `docker compose` with that message when one is missing: there is no default to forget to change.","The services publish ports 8081 to 8084, one per language. Python starts only once MongoDB is healthy, not merely started: Mongo's healthcheck pings it with `mongosh`, and `depends_on` waits for that. The `internal` network is marked `internal: true`, so it has no route to the outside world either, and only the Python service joins it."],examples:["secrets","mongo"]},{id:"ci",h:"Proved in CI",p:["CI builds the four images, waits until all of them are healthy, calls `/status` on each, and then checks the opposite: without the secrets, `docker compose config` must fail.","The secrets in CI are fresh random values from `openssl`, made for that run, and `--wait` makes `up` return only when every container is healthy, so the curl loop never races a service still starting."],examples:["job"]}],fa:[{id:"compose",h:"بدون secret پیش‌فرض",p:["درس‌های Docker همان چهار بک‌اند را بسته‌بندی می‌کنند. یک فایل compose آن‌ها را با یک MongoDB می‌سازد که هیچ پورتی باز نمی‌کند و روی شبکه‌ی `internal` است که فقط سرویس Python به آن وصل است. secretها از environment می‌آیند و `${VAR:?message}` اگر یکی نباشد `docker compose` را با همان پیام متوقف می‌کند: مقدار پیش‌فرضی نیست که یادت برود عوضش کنی.","سرویس‌ها پورت‌های 8081 تا 8084 را منتشر می‌کنند، یکی برای هر زبان. Python فقط وقتی شروع می‌شود که MongoDB سالم باشد، نه صرفاً روشن: healthcheck‌ی Mongo با `mongosh` آن را ping می‌کند، و `depends_on` منتظر همان می‌ماند. شبکه‌ی `internal` با `internal: true` علامت خورده، پس به دنیای بیرون هم راهی ندارد، و فقط سرویس Python به آن می‌پیوندد."],examples:["secrets","mongo"]},{id:"ci",h:"اثبات‌شده در CI",p:["CI چهار image را می‌سازد، صبر می‌کند تا همه healthy شوند، `/status` هر کدام را صدا می‌زند، و بعد برعکسش را چک می‌کند: بدون secretها `docker compose config` باید شکست بخورد.","secretها در CI مقدارهای تصادفی تازه از `openssl`اند، ساخته‌شده برای همان اجرا، و `--wait` باعث می‌شود `up` فقط وقتی برگردد که همه‌ی containerها سالم باشند، پس حلقه‌ی curl هیچ‌وقت با سرویسی که هنوز در حال شروع است مسابقه نمی‌دهد."],examples:["job"]}],examples:{secrets:{title:{en:"Required, with a message",fa:"اجباری، با یک پیام"},lang:"yaml",file:"examples/docker/compose.yml",from:"x-secrets: &secrets",lines:3},job:{title:{en:"Healthy, then refused",fa:"healthy، بعد رد"},lang:"yaml",file:".github/workflows/deploy-pages.yml",from:"- name: Build the four images",lines:8},mongo:{title:{en:"No published port, healthy before use",fa:"بدون پورت منتشرشده، سالم پیش از استفاده"},lang:"yaml",file:"examples/docker/compose.yml",from:"image: mongo:7",lines:9}},quiz:[{q:{en:"`JWT_SECRET` is not set and you run `docker compose up`. What happens?",fa:"`JWT_SECRET` تنظیم نشده و `docker compose up` را اجرا می‌کنید. چه می‌شود؟"},options:{en:["Compose stops with the message written after `:?`","The services start with an empty secret","A default secret from the file is used"],fa:["Compose با پیامی که بعد از `:?` نوشته شده متوقف می‌شود","سرویس‌ها با secret خالی شروع می‌شوند","یک secret پیش‌فرض از فایل استفاده می‌شود"]},answer:0,why:{en:"`${VAR:?message}` makes a missing variable an error, so there is no default to forget to change.",fa:"`${VAR:?message}` نبودن متغیر را به خطا تبدیل می‌کند، پس پیش‌فرضی نیست که تغییرش فراموش شود."}},{q:{en:"Can the C# service reach MongoDB in this compose file?",fa:"در این فایل compose سرویس C# می‌تواند به MongoDB برسد؟"},options:{en:["Yes, through port 27017 on the host","No: Mongo publishes no port and only the Python service is on the `internal` network","Yes, every service shares one network"],fa:["بله، از راه پورت 27017 روی host","نه: Mongo هیچ پورتی منتشر نمی‌کند و فقط سرویس Python روی شبکه‌ی `internal` است","بله، همه‌ی سرویس‌ها یک شبکه دارند"]},answer:1,why:{en:"A service reaches another only on a network they share.",fa:"یک سرویس فقط روی شبکه‌ای که مشترک دارند به دیگری می‌رسد."}},{q:{en:"Why does CI also run `docker compose config` without the secrets?",fa:"چرا CI `docker compose config` را بدون secretها هم اجرا می‌کند؟"},options:{en:["To print the file","To warm the image cache","To prove the opposite case: compose must refuse to start, and the step fails if it doesn't"],fa:["تا فایل را چاپ کند","تا cache‌ی imageها گرم شود","تا حالت مخالف را ثابت کند: compose باید از شروع سر باز بزند، و اگر نزند step شکست می‌خورد"]},answer:2,why:{en:"A test that only checks the happy path would miss a default secret slipping back in.",fa:"تستی که فقط مسیر موفق را چک کند برگشتن بی‌صدای یک secret پیش‌فرض را نمی‌دید."}}]},{id:"ops",group:"examples",title:{en:"Ops scripts in three languages",fa:"اسکریپت‌های عملیات در سه زبان"},files:["examples/ops/Dockerfile","examples/ops/tests/run.sh","examples/ops/deploy/deploy.sh"],en:[{id:"image",h:"An Ubuntu like the VPS",p:["The ops lessons (safe scripts, server setup, release, deploy, backup, restore test, CI/CD, reverse proxy) write each script in Bash, PowerShell and Python. They are not just linted: an Ubuntu 24.04 container with all three shells, a real `sshd`, git and sqlite runs every one of them."],examples:["image"]},{id:"check",h:"One check for every language",p:["`tests/run.sh` runs the same scenario in each language and checks the exit code and the output: the deploy refuses a second run while one holds the lock, the release stops when the repo is behind, the SSH hardening leaves a config that `sshd -t` accepts. A failing check is counted and the next one still runs. Before that, CI runs shellcheck, PSScriptAnalyzer and actionlint; Caddy and nginx are tested with curl in front of an app.","`check` takes an exit code (or `fail` for any non-zero one) and a text the output must contain, or with a leading `!` must not. It prints every failing case with its output, and the last line exits non-zero when anything failed, so the CI step fails while the log still shows every result. The CI deploy is tested the same way over a real SSH connection: a forced command deploys whatever was asked, and port forwarding or a wrong host key is refused."],examples:["check","forced","summary"]}],fa:[{id:"image",h:"یک Ubuntu مثل VPS",p:["درس‌های عملیات (اسکریپت امن، راه‌اندازی سرور، انتشار، استقرار، بکاپ، تست بازگردانی، CI/CD، reverse proxy) هر اسکریپت را در Bash، PowerShell و Python می‌نویسند. فقط lint نمی‌شوند: یک کانتینر Ubuntu 24.04 با هر سه shell، یک `sshd` واقعی، git و sqlite تک‌تکشان را اجرا می‌کند."],examples:["image"]},{id:"check",h:"یک چک برای همه‌ی زبان‌ها",p:["`tests/run.sh` همان سناریو را در هر زبان اجرا می‌کند و کد خروج و خروجی را چک می‌کند: deploy اجرای دوم را تا وقتی قفل دست اولی است رد می‌کند، release وقتی repo عقب است متوقف می‌شود، سخت‌کردن SSH تنظیمی باقی می‌گذارد که `sshd -t` قبولش دارد. چکی که شکست بخورد شمرده می‌شود و چک بعدی باز هم اجرا می‌شود. قبل از آن CI ابزارهای shellcheck، PSScriptAnalyzer و actionlint را اجرا می‌کند؛ Caddy و nginx با curl جلوی یک اپ تست می‌شوند.","`check` یک کد خروج (یا `fail` برای هر کد غیرصفر) و متنی می‌گیرد که خروجی باید داشته باشد، یا با `!` در ابتدا نباید داشته باشد. هر حالت شکست‌خورده را با خروجی‌اش چاپ می‌کند، و آخرین سطر وقتی چیزی شکست خورده باشد با کد غیرصفر خارج می‌شود، پس step‌ی CI شکست می‌خورد در حالی که log همچنان همه‌ی نتیجه‌ها را نشان می‌دهد. deploy‌ی CI هم به همین شکل روی یک اتصال SSH واقعی تست می‌شود: یک forced command هر چه خواسته شود فقط deploy می‌کند، و port forwarding یا host key اشتباه رد می‌شود."],examples:["check","forced","summary"]}],examples:{image:{title:{en:"Three shells in one image",fa:"سه shell در یک image"},lang:"dockerfile",file:"examples/ops/Dockerfile",from:"FROM ubuntu:24.04",to:"rm -rf /var/lib/apt/lists/*"},check:{title:{en:"check: exit code and output",fa:"check: کد خروج و خروجی"},lang:"bash",file:"examples/ops/tests/run.sh",from:"# check <name> <exit",lines:18},forced:{title:{en:"Whatever is asked, it only deploys",fa:"هر چه خواسته شود، فقط deploy می‌کند"},lang:"bash",file:"examples/ops/tests/run.sh",from:'check "no command: it deploys"',lines:2},summary:{title:{en:"Counted, then the exit code",fa:"شمرده، بعد کد خروج"},lang:"bash",file:"examples/ops/tests/run.sh",from:'echo "$passed passed, $failed failed"',lines:2}},quiz:[{q:{en:"Why does `tests/run.sh` not use `set -e`?",fa:"چرا `tests/run.sh` از `set -e` استفاده نمی‌کند؟"},options:{en:["PowerShell can't run under it","So a failing check is counted and the next one still runs","It is slower"],fa:["PowerShell زیر آن اجرا نمی‌شود","تا check شکست‌خورده شمرده شود و بعدی باز هم اجرا شود","کندتر است"]},answer:1,why:{en:"With `-e` the first failure would hide every result after it; the final line still fails the run.",fa:"با `-e` اولین شکست همه‌ی نتیجه‌های بعدی را پنهان می‌کرد؛ آخرین سطر باز هم اجرا را شکست می‌دهد."}},{q:{en:"Why are the scripts run in an Ubuntu 24.04 container with a real `sshd` rather than only linted?",fa:"چرا اسکریپت‌ها در یک container‌ی Ubuntu 24.04 با `sshd` واقعی اجرا می‌شوند، نه فقط lint؟"},options:{en:["A linter can't tell that the SSH hardening leaves a config `sshd -t` accepts, or that a second deploy waits for the lock","Linters don't support PowerShell","GitHub's runners have no bash"],fa:["linter نمی‌تواند بگوید سخت‌سازی SSH پیکربندی‌ای باقی می‌گذارد که `sshd -t` می‌پذیرد، یا این‌که deploy دوم منتظر lock می‌ماند","linterها PowerShell را پشتیبانی نمی‌کنند","runnerهای GitHub bash ندارند"]},answer:0,why:{en:"The container is the same release as the VPS, so behaviour, not just syntax, is checked.",fa:"container همان نسخه‌ی VPS است، پس رفتار چک می‌شود، نه فقط نحو."}}]},{id:"page",group:"reading",title:{en:"The lesson page",fa:"صفحه‌ی درس"},files:["src/components/LessonBody.vue","src/components/CodeTabs.vue","src/components/CompareTable.vue","src/lib/highlight.ts"],en:[{id:"body",h:"One component for the screen and for paper",p:["`LessonBody` lays a lesson out in its fixed order. Given `booklet`, it shows every language one under the other and opens every exercise answer, which is how it is printed. Samples are grouped by `group` in the order they are written.","The comparison table highlights the column of the language the reader already knows, and each cell carries its language's name as a label, so on a phone, where the table becomes a list, a cell still says which language it is."],examples:["groups"]},{id:"tabs",h:"Tabs that say where the code is from",p:["Each block shows its origin under the tab: tested code, shortened real code, or a port. highlight.js colours it, with only the languages the lessons use registered, so the bundle stays small; it escapes the source, which is why `v-html` is safe here.",'The tabs follow the lesson\'s order of languages, with a sample for every language first. The code is `dir="ltr"` even on the Persian page. The copy button writes the code to the clipboard inside a try, because the clipboard is refused outside a secure context; the code stays selectable either way.'],examples:["origin","copy"]}],fa:[{id:"body",h:"یک کامپوننت برای صفحه و برای کاغذ",p:["`LessonBody` درس را به همان ترتیب ثابتش می‌چیند. با `booklet` همه‌ی زبان‌ها را زیر هم نشان می‌دهد و پاسخ همه‌ی تمرین‌ها را باز می‌کند؛ نسخه‌ی چاپی همین است. نمونه‌ها بر اساس `group` و به ترتیبی که نوشته شده‌اند گروه می‌شوند.","جدول مقایسه ستون زبانی را که خواننده از قبل می‌شناسد برجسته می‌کند، و هر خانه اسم زبانش را به‌صورت برچسب دارد، پس روی گوشی، جایی که جدول به فهرست تبدیل می‌شود، هر خانه باز هم می‌گوید کدام زبان است."],examples:["groups"]},{id:"tabs",h:"تب‌هایی که می‌گویند کد از کجاست",p:["هر بلوک زیر تب، منشأ کد را نشان می‌دهد: کد تست‌شده، کد واقعیِ کوتاه‌شده، یا ترجمه. highlight.js رنگش می‌کند و فقط زبان‌هایی که درس‌ها لازم دارند در آن ثبت شده‌اند تا bundle کوچک بماند؛ متن منبع را escape می‌کند و به همین دلیل `v-html` این‌جا امن است.",'تب‌ها از ترتیب زبان‌های درس پیروی می‌کنند، و sampleی که برای همه‌ی زبان‌هاست اول می‌آید. کد حتی روی صفحه‌ی فارسی `dir="ltr"` است. دکمه‌ی کپی کد را داخل یک try در clipboard می‌نویسد، چون بیرون از secure context به clipboard اجازه داده نمی‌شود؛ کد در هر حال قابل انتخاب می‌ماند.'],examples:["origin","copy"]}],examples:{groups:{title:{en:"Samples into blocks",fa:"نمونه‌ها در بلوک‌ها"},lang:"typescript",file:"src/components/LessonBody.vue",from:"// Samples that share a `group`",lines:6},origin:{title:{en:"The three origins",fa:"سه منشأ"},lang:"typescript",file:"src/components/CodeTabs.vue",from:"const ORIGIN",lines:5},copy:{title:{en:"Copy, if the browser allows it",fa:"کپی، اگر مرورگر اجازه بدهد"},lang:"typescript",file:"src/components/CodeTabs.vue",from:"async function copy(s: CodeSample) {",lines:9}},quiz:[{q:{en:"Why is `v-html` safe for the highlighted code?",fa:"چرا `v-html` برای کد رنگ‌آمیزی‌شده امن است؟"},options:{en:["The code comes from trusted files","highlight.js escapes the source before adding its own markup","Vue sanitises `v-html`"],fa:["کد از فایل‌های قابل‌اعتماد می‌آید","highlight.js پیش از اضافه کردن markup خودش منبع را escape می‌کند","Vue محتوای `v-html` را پاک‌سازی می‌کند"]},answer:1,why:{en:"A `<` in the code becomes `&lt;`, so only highlight.js's spans are real HTML.",fa:"یک `<` در کد به `&lt;` تبدیل می‌شود، پس فقط spanهای highlight.js HTML واقعی‌اند."}},{q:{en:"How does the booklet show every language and every answer while the screen shows tabs and closed answers?",fa:"جزوه چطور همه‌ی زبان‌ها و همه‌ی جواب‌ها را نشان می‌دهد در حالی که صفحه تب و جواب بسته نشان می‌دهد؟"},options:{en:["A separate booklet component","Print CSS opens them","The same `LessonBody` with `booklet` set, which shows all samples and opens every exercise"],fa:["یک کامپوننت جدا برای جزوه","CSS چاپ آن‌ها را باز می‌کند","همان `LessonBody` با `booklet`، که همه‌ی sampleها را نشان می‌دهد و هر تمرین را باز می‌کند"]},answer:2,why:{en:"One component for screen and paper means the two can't drift apart.",fa:"یک کامپوننت برای صفحه و کاغذ یعنی این دو نمی‌توانند از هم جدا بیفتند."}},{q:{en:"Why are only some highlight.js languages registered?",fa:"چرا فقط بعضی از زبان‌های highlight.js ثبت شده‌اند؟"},options:{en:["To keep the bundle small","The others are buggy","The licence allows only these"],fa:["تا باندل کوچک بماند","بقیه باگ دارند","مجوز فقط همین‌ها را اجازه می‌دهد"]},answer:0,why:{en:"The core build plus the grammars the lessons use; `plaintext` is registered because the fallback needs it.",fa:"build هسته به‌علاوه‌ی grammarهایی که درس‌ها استفاده می‌کنند؛ `plaintext` ثبت شده چون fallback لازمش دارد."}}]},{id:"booklets",group:"reading",title:{en:"Booklets and PDFs",fa:"جزوه‌ها و PDFها"},files:["src/views/BookletView.vue","src/lib/booklets.ts","scripts/pdf.mjs","src/styles/base/_print.scss"],en:[{id:"page",h:"A booklet is a page",p:["`#/booklet/<tag>` puts every lesson of one booklet on a single page, fully expanded, with a table of contents. The router owns the URL's hash, so the contents scroll by script rather than with `#anchors`. Print styles hide the navigation and turn the code dark-on-light for paper."]},{id:"pdf",h:"Printed by CI",p:["After the build, CI serves the site with `vite preview` and Playwright prints each booklet page to A4, waiting for the fonts first so the Persian text is not set in a fallback. Each booklet gets a fresh page: only the hash differs between them, and a hash change on the same page is not a load.","The Persian text is set in Vazirmatn, bundled with the site rather than fetched from a font service; printing before it has loaded would freeze the fallback font into the PDF. Each PDF gets page numbers in its footer, and print has its own colour map, so syntax colours stay dark enough for a laser printer."],examples:["print"]},{id:"base",h:"Where the PDFs are",p:["The PDFs exist only on GitHub Pages, next to the site CI built. The VPS build has none of its own and links to those, through `VITE_PDF_BASE`."],examples:["pdfbase"]}],fa:[{id:"page",h:"جزوه یک صفحه است",p:["`#/booklet/<tag>` همه‌ی درس‌های یک جزوه را کامل و باز روی یک صفحه با فهرست مطالب می‌گذارد. hash آدرس مال router است، پس فهرست با اسکریپت scroll می‌کند نه با `#anchor`. استایل چاپ ناوبری را پنهان می‌کند و کد را برای کاغذ تیره روی روشن می‌کند."]},{id:"pdf",h:"چاپ‌شده در CI",p:["بعد از build، CI سایت را با `vite preview` سرو می‌کند و Playwright صفحه‌ی هر جزوه را در A4 چاپ می‌کند، و اول صبر می‌کند فونت‌ها بار شوند تا متن فارسی با فونت جایگزین چیده نشود. هر جزوه صفحه‌ی تازه‌ی خودش را می‌گیرد: بین آن‌ها فقط hash فرق دارد، و عوض شدن hash در همان صفحه بار شدن حساب نمی‌شود.","متن فارسی با Vazirmatn چیده می‌شود، که همراه سایت باندل شده نه این‌که از یک سرویس فونت گرفته شود؛ چاپ پیش از بار شدنش فونت جایگزین را در PDF ثابت می‌کرد. هر PDF در پانویسش شماره‌ی صفحه دارد، و چاپ نقشه‌ی رنگ خودش را دارد، پس رنگ‌های کد برای یک چاپگر لیزری به اندازه‌ی کافی تیره می‌مانند."],examples:["print"]},{id:"base",h:"PDFها کجا هستند",p:["PDFها فقط روی GitHub Pages هستند، کنار سایتی که CI ساخته. build روی VPS هیچ PDFی از خودش ندارد و از طریق `VITE_PDF_BASE` به همان‌ها لینک می‌دهد."],examples:["pdfbase"]}],examples:{print:{title:{en:"One booklet, one page, one PDF",fa:"یک جزوه، یک صفحه، یک PDF"},lang:"javascript",file:"scripts/pdf.mjs",from:"for (const tag of BOOKLETS) {",to:"await page.evaluate(() => document.fonts.ready)"},pdfbase:{title:{en:"PDF_BASE",fa:"PDF_BASE"},lang:"typescript",file:"src/lib/booklets.ts",from:"// Where the booklet PDFs live.",lines:3}},quiz:[{q:{en:"Why does the script open a new page for each booklet instead of changing the hash?",fa:"چرا اسکریپت برای هر جزوه صفحه‌ی تازه‌ای باز می‌کند به جای عوض کردن hash؟"},options:{en:["Playwright can't change a hash","A hash change on the same page is not a load, so waiting for the network would return at once","Each booklet needs a different base"],fa:["Playwright نمی‌تواند hash را عوض کند","تغییر hash در همان صفحه بار شدن نیست، پس منتظر شبکه ماندن فوراً برمی‌گشت","هر جزوه base متفاوتی لازم دارد"]},answer:1,why:{en:"A fresh page makes `goto` a real load, so `networkidle` and the fonts mean something.",fa:"صفحه‌ی تازه `goto` را یک بار شدن واقعی می‌کند، پس `networkidle` و فونت‌ها معنا پیدا می‌کنند."}},{q:{en:"Why does the table of contents scroll by script rather than with `#anchors`?",fa:"چرا فهرست مطالب به جای `#anchor` با اسکریپت اسکرول می‌کند؟"},options:{en:["The router owns the URL's hash; an anchor would be read as a route","Anchors don't work in print","Script scrolling is smoother on phones"],fa:["router صاحب hash آدرس است؛ anchor به‌عنوان route خوانده می‌شد","anchorها در چاپ کار نمی‌کنند","اسکرول اسکریپتی روی گوشی نرم‌تر است"]},answer:0,why:{en:"`#lesson-id` would replace `#/booklet/backend` and leave the page.",fa:"`#lesson-id` جای `#/booklet/backend` را می‌گرفت و از صفحه بیرون می‌رفت."}},{q:{en:"The VPS build has no PDFs. How do its download links work?",fa:"build‌ی VPS هیچ PDFی ندارد. لینک‌های دانلودش چطور کار می‌کنند؟"},options:{en:["The VPS prints them at start","They are hidden","`VITE_PDF_BASE` points them at the PDFs CI published on GitHub Pages"],fa:["VPS موقع شروع آن‌ها را چاپ می‌کند","پنهان می‌شوند","`VITE_PDF_BASE` آن‌ها را به PDFهایی که CI روی GitHub Pages منتشر کرده می‌فرستد"]},answer:2,why:{en:"Without it, `PDF_BASE` falls back to `pdf/` under the site's own base.",fa:"بدون آن، `PDF_BASE` به `pdf/` زیر base خود سایت برمی‌گردد."}}]},{id:"review",group:"reading",title:{en:"Review cards",fa:"کارت‌های مرور"},files:["src/lib/review.ts","src/views/ReviewView.vue"],en:[{id:"cards",h:"Cards made from the lessons",p:["Nobody writes review cards by hand. Each comparison row becomes a card (the C# answer as the hint, the other languages on the back), and so does each common mistake and each exercise.","A card's id is the lesson's id and the item's place, like `l002:c3`, so progress survives a rebuild. Adding a lesson adds its cards on their own; reordering a lesson's rows, though, gives the moved ones another card's history. A mistake's card asks what is wrong with it and answers with the reason and the fix."]},{id:"leitner",h:"Leitner boxes",p:["A right answer moves a card up a box and pushes it further away: tomorrow, then 3, 7, 16 and 35 days. A wrong answer puts it back in box 1 and at the end of today's queue, so it comes back before the session ends. A day brings every card that is due plus at most 15 new ones."],examples:["grade","due"]},{id:"storage",h:"Kept in this browser",p:["Progress lives in `localStorage` and nowhere else. When storage is blocked or the saved value is broken, the page starts from nothing instead of failing.","Saving is wrapped the same way: in a private window progress simply isn't kept. The key carries a version, `pld-review-v1`, so a future change to the saved shape can start under a new key instead of misreading the old one."],examples:["load"]}],fa:[{id:"cards",h:"کارت‌هایی که از درس‌ها ساخته می‌شوند",p:["هیچ‌کس کارت مرور را دستی نمی‌نویسد. هر ردیف مقایسه یک کارت می‌شود (جواب C# به‌عنوان راهنما، بقیه‌ی زبان‌ها پشت کارت)، و هر اشتباه رایج و هر تمرین هم همین‌طور.","id هر کارت id درس و جای آن قلم است، مثل `l002:c3`، پس پیشرفت بعد از build دوباره باقی می‌ماند. اضافه شدن یک درس کارت‌هایش را خودبه‌خود اضافه می‌کند؛ ولی جابه‌جا کردن ردیف‌های یک درس تاریخچه‌ی کارت دیگری را به ردیف‌های جابه‌جاشده می‌دهد. کارت یک اشتباه می‌پرسد چه اشکالی دارد و با دلیل و راه درست جواب می‌دهد."]},{id:"leitner",h:"جعبه‌های لایتنر",p:["جواب درست کارت را یک جعبه بالا می‌برد و دورترش می‌کند: فردا، بعد ۳، ۷، ۱۶ و ۳۵ روز. جواب غلط آن را به جعبه‌ی ۱ و ته صف امروز برمی‌گرداند، پس قبل از تمام شدن جلسه دوباره می‌آید. هر روز همه‌ی کارت‌های سررسیده می‌آیند و حداکثر ۱۵ کارت تازه."],examples:["grade","due"]},{id:"storage",h:"نگه‌داشته در همین مرورگر",p:["پیشرفت فقط در `localStorage` است و هیچ‌جای دیگر. اگر storage بسته باشد یا مقدار ذخیره‌شده خراب باشد، صفحه به‌جای خطا از صفر شروع می‌کند.","ذخیره کردن هم همین‌طور محافظت شده: در پنجره‌ی خصوصی پیشرفت فقط نگه داشته نمی‌شود. کلید یک نسخه دارد، `pld-review-v1`، پس تغییری در آینده در شکل ذخیره‌شده می‌تواند زیر کلید تازه‌ای شروع شود به جای این‌که قدیمی را اشتباه بخواند."],examples:["load"]}],examples:{grade:{title:{en:"Up a box, or back to one",fa:"یک جعبه بالا، یا برگشت به یک"},lang:"typescript",file:"src/lib/review.ts",from:"export function grade(",lines:5},due:{title:{en:"Today's cards",fa:"کارت‌های امروز"},lang:"typescript",file:"src/lib/review.ts",from:"export function dueCards(",lines:5},load:{title:{en:"Storage that may not be there",fa:"storageی که شاید نباشد"},lang:"typescript",file:"src/lib/review.ts",from:"export function loadState()",lines:7}},quiz:[{q:{en:"A card in box 3 is answered wrong. When is it due?",fa:"کارتی در جعبه‌ی ۳ اشتباه جواب داده می‌شود. کی دوباره می‌آید؟"},options:{en:["In 7 days","Tomorrow, from box 1","In 3 days"],fa:["هفت روز بعد","فردا، از جعبه‌ی ۱","سه روز بعد"]},answer:1,why:{en:"A wrong answer always goes back to box 1, whose interval is one day.",fa:"جواب اشتباه همیشه به جعبه‌ی ۱ برمی‌گردد، که فاصله‌اش یک روز است."}},{q:{en:"The saved progress in `localStorage` is corrupted JSON. What does the review page do?",fa:"پیشرفت ذخیره‌شده در `localStorage` یک JSON خراب است. صفحه‌ی مرور چه می‌کند؟"},options:{en:["Starts from nothing and keeps working","Shows an error and stops","Deletes the lessons"],fa:["از صفر شروع می‌کند و کار می‌کند","خطا نشان می‌دهد و می‌ایستد","درس‌ها را پاک می‌کند"]},answer:0,why:{en:"`loadState` catches the parse error and returns an empty state.",fa:"`loadState` خطای parse را می‌گیرد و یک وضعیت خالی برمی‌گرداند."}},{q:{en:"Where do the review cards come from?",fa:"کارت‌های مرور از کجا می‌آیند؟"},options:{en:["A separate file of hand-written cards","A server that picks them","Each lesson's comparison rows, common mistakes and exercises"],fa:["فایلی جدا از کارت‌های دست‌نویس","سروری که انتخابشان می‌کند","ردیف‌های مقایسه، اشتباه‌های رایج و تمرین‌های هر درس"]},answer:2,why:{en:"`cardsFor` turns a lesson into cards, so a new lesson brings its cards with it.",fa:"`cardsFor` یک درس را به کارت تبدیل می‌کند، پس درس تازه کارت‌هایش را با خود می‌آورد."}}]},{id:"offline",group:"reading",title:{en:"Installable and offline",fa:"نصب‌شدنی و آفلاین"},files:["public/sw.js","public/manifest.webmanifest","src/main.ts","index.html"],en:[{id:"sw",h:"Network first, then the last copy",p:["A manifest makes the site installable as an app. The service worker is eighteen lines: it asks the network first and stores each answer, and when the network fails it serves the last copy. A lesson read once therefore opens on a train. It only handles GET requests to its own origin.","It is registered only in a production build, so the dev server is never served from a stale cache.","Network first is chosen over cache first on purpose: online, the reader always gets the latest deploy, and the cache is only a fallback. A cache-first worker would keep showing yesterday's lessons until it was replaced."],examples:["sw","register"]},{id:"versions",h:"One cache, and a quick takeover",p:["Everything goes into one cache, `pld-v1`. A new worker skips waiting, so it takes over as soon as it is installed instead of after every tab is closed, and on activation it deletes every other cache and claims the open pages. Changing the cache's name in a later version therefore clears the old copies.","Each answer is cloned before it is stored, because a response's body can be read only once: one copy goes to the page, the other to the cache. Registration uses `BASE_URL`, so the worker's scope is the site's own folder on GitHub Pages and the root on the VPS, and a failed registration is ignored: the site still works, just not offline."]}],fa:[{id:"sw",h:"اول شبکه، بعد آخرین کپی",p:["یک manifest سایت را به شکل اپ نصب‌شدنی می‌کند. service worker هجده خط است: اول از شبکه می‌پرسد و هر جواب را نگه می‌دارد، و وقتی شبکه نباشد آخرین کپی را می‌دهد. پس درسی که یک بار خوانده شده در قطار هم باز می‌شود. فقط درخواست‌های GET به origin خودش را جواب می‌دهد.","فقط در build production ثبت می‌شود، پس dev server هیچ‌وقت از cache کهنه سرو نمی‌شود.","network first عمداً به جای cache first انتخاب شده: وقتی آنلاین است، خواننده همیشه آخرین استقرار را می‌گیرد، و cache فقط پشتیبان است. worker‌ی cache-first درس‌های دیروز را تا وقتی جایگزین شود نشان می‌داد."],examples:["sw","register"]},{id:"versions",h:"یک cache، و جانشینی سریع",p:["همه چیز در یک cache می‌رود، `pld-v1`. worker تازه منتظر نمی‌ماند، پس به محض نصب کار را به دست می‌گیرد نه بعد از بسته شدن همه‌ی تب‌ها، و هنگام فعال شدن هر cache دیگری را پاک می‌کند و صفحه‌های باز را تحویل می‌گیرد. پس عوض کردن اسم cache در نسخه‌ی بعدی نسخه‌های قدیمی را پاک می‌کند.","هر جواب پیش از ذخیره clone می‌شود، چون بدنه‌ی یک response فقط یک بار خواندنی است: یک نسخه به صفحه می‌رود، دیگری به cache. ثبت از `BASE_URL` استفاده می‌کند، پس scope‌ی worker پوشه‌ی خود سایت روی GitHub Pages و ریشه روی VPS است، و ثبت ناموفق نادیده گرفته می‌شود: سایت باز هم کار می‌کند، فقط آفلاین نه."]}],examples:{sw:{title:{en:"The whole service worker",fa:"کل service worker"},lang:"javascript",file:"public/sw.js",from:"// Minimal offline shell",lines:18},register:{title:{en:"Registered in production only",fa:"ثبت فقط در production"},lang:"typescript",file:"src/main.ts",from:"// Installable app",lines:4}},quiz:[{q:{en:"Why is the service worker registered only in a production build?",fa:"چرا service worker فقط در build‌ی production ثبت می‌شود؟"},options:{en:["So the dev server is never served from a stale cache","Workers don't run on localhost","Vite forbids it"],fa:["تا dev server هیچ‌وقت از یک cache کهنه سرو نشود","workerها روی localhost اجرا نمی‌شوند","Vite منعش می‌کند"]},answer:0,why:{en:"During development every edit must show at once; a cached copy would hide it.",fa:"در توسعه هر ویرایشی باید فوراً دیده شود؛ نسخه‌ی cacheشده آن را پنهان می‌کرد."}},{q:{en:"The reader is online and a new version was deployed an hour ago. What do they see?",fa:"خواننده آنلاین است و نسخه‌ی تازه‌ای یک ساعت پیش مستقر شده. چه می‌بیند؟"},options:{en:["The cached version until they clear the cache","The new version: the network is asked first","A prompt to update"],fa:["نسخه‌ی cacheشده تا cache را پاک کند","نسخه‌ی تازه: اول از شبکه پرسیده می‌شود","پیامی برای به‌روزرسانی"]},answer:1,why:{en:"The cache is used only when the network fails.",fa:"cache فقط وقتی استفاده می‌شود که شبکه شکست بخورد."}},{q:{en:"Why is each response cloned before it is put in the cache?",fa:"چرا هر response پیش از گذاشتن در cache کلون می‌شود؟"},options:{en:["To compress it","To strip cookies","A body can be read only once, and both the page and the cache need it"],fa:["تا فشرده شود","تا کوکی‌ها حذف شوند","بدنه فقط یک بار خواندنی است، و هم صفحه و هم cache لازمش دارند"]},answer:2,why:{en:"Without the clone, storing it would consume the body the page is waiting for.",fa:"بدون clone، ذخیره کردن بدنه‌ای را که صفحه منتظرش است مصرف می‌کرد."}}]},{id:"map",group:"projects",title:{en:"The system map, read from compose",fa:"نقشه‌ی سیستم، خوانده از compose"},files:["scripts/project-map.mjs","src/data/project-map.json"],en:[{id:"sources",h:"Read from the files that run the portfolio",p:["Nothing on the system map is drawn by hand. `npm run map` reads Control Panel's compose files, the VPS overlay, the Caddyfile and the VPS env template, only reading them, and writes `src/data/project-map.json`: which project each service belongs to, what it talks to, and which domain Caddy sends to it."],examples:["sources"]},{id:"links",h:"Who talks to whom",p:["A service talks to another when its environment names it (a host in a URL or a connection string) or it `depends_on` it. A database named after a project's repo is that project's data, so reading it links the two projects even when it lives on the shared SQL Server. Caddy's site blocks give the public face: each domain, its service, and whether it is behind basic auth."],examples:["owner","sites"]},{id:"check",h:"Out of date is a failure",p:["With `--check` the script compares its result with the committed map and fails when they differ, so a compose change in Control Panel that is not mapped here stops `npm run check`. CI has no copy of Control Panel and uses the committed map as it is."],examples:["check"]}],fa:[{id:"sources",h:"خوانده از فایل‌هایی که پورتفولیو را اجرا می‌کنند",p:["هیچ‌چیز روی نقشه‌ی سیستم دستی کشیده نشده. `npm run map` فایل‌های compose کنترل پنل، overlay مخصوص VPS، Caddyfile و الگوی env روی VPS را فقط می‌خواند و `src/data/project-map.json` را می‌نویسد: هر سرویس مال کدام پروژه است، با چه چیزی حرف می‌زند، و Caddy کدام دامنه را به آن می‌فرستد."],examples:["sources"]},{id:"links",h:"چه کسی با چه کسی حرف می‌زند",p:["یک سرویس با سرویس دیگر حرف می‌زند وقتی environmentاش اسم آن را می‌آورد (host در یک URL یا connection string) یا `depends_on` آن است. دیتابیسی که هم‌نام repo یک پروژه است داده‌ی همان پروژه است، پس خواندنش دو پروژه را به هم وصل می‌کند، حتی وقتی روی SQL Server مشترک است. بلوک‌های سایت در Caddyfile چهره‌ی عمومی را می‌دهند: هر دامنه، سرویسش، و این‌که پشت basic auth هست یا نه."],examples:["owner","sites"]},{id:"check",h:"کهنه بودن یعنی خطا",p:["با `--check` اسکریپت نتیجه‌اش را با نقشه‌ی commit‌شده مقایسه می‌کند و اگر فرق داشته باشند خطا می‌دهد، پس تغییری در compose کنترل پنل که این‌جا روی نقشه نیامده `npm run check` را متوقف می‌کند. CI کپی کنترل پنل را ندارد و از همان نقشه‌ی commit‌شده استفاده می‌کند."],examples:["check"]}],examples:{sources:{title:{en:"The five files it reads",fa:"پنج فایلی که می‌خواند"},lang:"javascript",file:"scripts/project-map.mjs",from:"const SOURCES = {",lines:7},owner:{title:{en:"A database that belongs to a project",fa:"دیتابیسی که مال یک پروژه است"},lang:"javascript",file:"scripts/project-map.mjs",from:"// A database named after a project's repo",lines:3},sites:{title:{en:"Caddy's sites",fa:"سایت‌های Caddy"},lang:"javascript",file:"scripts/project-map.mjs",from:"for (const m of caddyfile.matchAll(",lines:13},check:{title:{en:"Compared with the committed map",fa:"مقایسه با نقشه‌ی commit‌شده"},lang:"javascript",file:"scripts/project-map.mjs",from:"if (check) {",lines:7}},quiz:[{q:{en:"Someone adds a service to Control Panel's compose and pushes this repo without running `npm run map`. What happens locally?",fa:"کسی سرویسی به compose‌ی Control Panel اضافه می‌کند و این repo را بدون اجرای `npm run map` push می‌کند. روی ماشین محلی چه می‌شود؟"},options:{en:["`npm run check` fails: `--check` finds the committed map out of date","The map updates itself in the browser","Nothing, the map is drawn by hand"],fa:["`npm run check` شکست می‌خورد: `--check` نقشه‌ی commitشده را قدیمی می‌یابد","نقشه خودش در مرورگر به‌روز می‌شود","هیچ، نقشه دستی کشیده می‌شود"]},answer:0,why:{en:"The script compares what it would write with the committed file; in CI, with no Control Panel, it keeps the committed map.",fa:"اسکریپت آن‌چه می‌نوشت را با فایل commitشده مقایسه می‌کند؛ در CI، بدون Control Panel، نقشه‌ی commitشده را نگه می‌دارد."}},{q:{en:"A service in one project reads a database named `LabFlow` on the shared SQL Server. What does the map show?",fa:"سرویسی در یک پروژه دیتابیسی به اسم `LabFlow` را روی SQL Server مشترک می‌خواند. نقشه چه نشان می‌دهد؟"},options:{en:["Only a link to SQL Server","A link to SQL Server and a link to LabFlow, since a database named after a repo is that project's data","Nothing, databases aren't mapped"],fa:["فقط یک پیوند به SQL Server","پیوندی به SQL Server و پیوندی به LabFlow، چون دیتابیسی که اسم یک repo را دارد داده‌ی همان پروژه است","هیچ، دیتابیس‌ها نقشه نمی‌شوند"]},answer:1,why:{en:"The server alone would hide which project's data is being read.",fa:"سرور به‌تنهایی پنهان می‌کرد داده‌ی کدام پروژه خوانده می‌شود."}},{q:{en:"How does the map decide that one service talks to another?",fa:"نقشه چطور تصمیم می‌گیرد که سرویسی با سرویس دیگر حرف می‌زند؟"},options:{en:["From network traffic","From a hand-written list","Its environment names the other (a host in a URL or connection string), or it `depends_on` it"],fa:["از ترافیک شبکه","از یک فهرست دست‌نویس","environment آن دیگری را نام می‌برد (یک host در URL یا connection string)، یا با `depends_on` به آن وابسته است"]},answer:2,why:{en:"Everything comes from the files that run the portfolio, read only.",fa:"همه چیز از فایل‌هایی می‌آید که پورتفولیو را اجرا می‌کنند، فقط خوانده."}}]},{id:"topics",group:"projects",title:{en:"Topics and code snapshots",fa:"تاپیک‌ها و snapshotهای کد"},files:["src/projects/model.ts","scripts/project-code.mjs","src/data/topics/programminglessondesigner.json"],en:[{id:"file",h:"A project as topics",p:["Each project with topics has a file `src/data/topics/<project>.json` (this page comes from one): groups, and topics in them, each with its files, its sections in both languages, and the excerpts of real code it quotes. An excerpt names a file and a line of text to start from, and either a line to end at or a number of lines."],examples:["types"]},{id:"anchor",h:"Found by text, then snapshotted",p:["`npm run code` opens each project's repo, finds every excerpt by its text and writes `<project>.code.json` with the code, its line numbers, and the length of every file a topic lists. The site is built from these snapshots, so CI does not need the other repos. Locally, `--check` fails when a snapshot no longer matches its repo, or when an anchor is gone: an edit that moves the code elsewhere in the file does not.","Text anchors are the same idea as the lessons' regions, for code this repo doesn't own: the other repos have no markers, and their line numbers move with every edit. When the text is gone, the check says which excerpt lost its anchor, and the fix is to choose a new line of text, not to count lines. Recording each listed file's length lets the check also notice a file that was deleted or emptied, even when no excerpt quotes it."],examples:["find"]}],fa:[{id:"file",h:"یک پروژه به شکل تاپیک‌ها",p:["هر پروژه‌ای که تاپیک دارد یک فایل `src/data/topics/<project>.json` دارد (همین صفحه از یکی از آن‌ها آمده): گروه‌ها و تاپیک‌های داخلشان، هر کدام با فایل‌هایش، بخش‌هایش به هر دو زبان، و تکه‌های کد واقعی‌ای که نقل می‌کند. هر تکه یک فایل و یک خط متن برای شروع را نام می‌برد، و یا یک خط برای پایان یا تعداد خط‌ها را."],examples:["types"]},{id:"anchor",h:"پیدا شده با متن، بعد snapshot",p:["`npm run code` repo هر پروژه را باز می‌کند، هر تکه را با متنش پیدا می‌کند و `<project>.code.json` را با کد، شماره‌ی خط‌هایش و طول هر فایلی که تاپیکی فهرست کرده می‌نویسد. سایت از همین snapshotها build می‌شود، پس CI به repoهای دیگر نیازی ندارد. روی PC، `--check` وقتی snapshot دیگر با repoاش نخواند، یا متن شروعی دیگر نباشد، خطا می‌دهد؛ ویرایشی که کد را جای دیگری از فایل ببرد خطا نمی‌دهد.","anchorهای متنی همان فکر regionهای درس‌هاست، برای کدی که این repo صاحبش نیست: repoهای دیگر نشانگری ندارند، و شماره‌ی سطرهایشان با هر ویرایشی جابه‌جا می‌شود. وقتی متن از بین برود، check می‌گوید کدام excerpt anchorش را از دست داده، و راه درست انتخاب یک سطر متن تازه است، نه شمردن سطرها. ثبت طول هر فایل فهرست‌شده به check اجازه می‌دهد فایلی را هم که پاک یا خالی شده ببیند، حتی وقتی هیچ excerptی از آن نقل نکند."],examples:["find"]}],examples:{types:{title:{en:"A topic and its excerpts",fa:"یک تاپیک و تکه‌هایش"},lang:"typescript",file:"src/projects/model.ts",from:"export interface TopicExample {",lines:17},find:{title:{en:"From the anchor to the end",fa:"از متن شروع تا پایان"},lang:"javascript",file:"scripts/project-code.mjs",from:"const start = src.findIndex((l) => l.includes(ex.from))",lines:12}},quiz:[{q:{en:"Why is the site built from `<project>.code.json` instead of reading the other repos?",fa:"چرا سایت به جای خواندن repoهای دیگر از `<project>.code.json` ساخته می‌شود؟"},options:{en:["The snapshots are smaller","CI has no copy of the other repos; the snapshot carries the code they quote","The other repos are private on GitHub"],fa:["snapshotها کوچک‌ترند","CI هیچ نسخه‌ای از repoهای دیگر ندارد؛ snapshot کدی را که نقل می‌کنند حمل می‌کند","repoهای دیگر روی GitHub خصوصی‌اند"]},answer:1,why:{en:"Locally `--check` compares the snapshot with the repo, so it can't drift unnoticed.",fa:"روی ماشین محلی `--check` snapshot را با repo مقایسه می‌کند، پس بی‌خبر جدا نمی‌افتد."}},{q:{en:"Code an excerpt quotes is moved further down its file, unchanged. Does `--check` fail?",fa:"کدی که یک excerpt نقل می‌کند بدون تغییر پایین‌تر در فایلش جابه‌جا می‌شود. `--check` شکست می‌خورد؟"},options:{en:["No: the excerpt is found by its text, wherever it is","Yes, the line numbers changed","Only if the file got longer"],fa:["نه: excerpt با متنش پیدا می‌شود، هر جا باشد","بله، شماره‌ی سطرها عوض شده","فقط اگر فایل بلندتر شده باشد"]},answer:0,why:{en:"Only a lost anchor or different code fails it.",fa:"فقط anchor گم‌شده یا کد متفاوت آن را شکست می‌دهد."}}]},{id:"scanners",group:"projects",title:{en:"Tables read from the code",fa:"جدول‌هایی که از کد خوانده می‌شوند"},files:["scripts/project-code.mjs","src/components/projects/DataTable.vue"],en:[{id:"what",h:"Endpoints, tables, routes",p:["A topic can show a table instead of prose: a project's HTTP endpoints, its database tables, or its routes. The snapshot reads them from the code itself, each with a small reader per framework: NestJS controllers, Express apps and routers, ASP.NET Core Minimal APIs; SQL scripts, EF Core model snapshots and Mongoose schemas; Angular, React and Vue routes. They are regular expressions, not parsers, written against how these repos actually write their code.","The price of regular expressions is honesty about coverage: a route written in a style the reader doesn't know is simply missing from the table, never invented. A section can narrow a table to some areas or tables with `only`, and the topics check fails when a name there isn't in the snapshot, so a renamed controller or table shows up as a failure rather than an empty table."]},{id:"vue",h:"This site's own routes",p:["The routes table in “Three tabs and the router” comes from the Vue reader: a route's page, a page loaded on demand, or a redirect. The ASP.NET reader shows how far one goes: groups and their prefixes, then each endpoint's policy, from its own line or else its group's."],examples:["vue","aspnet"]}],fa:[{id:"what",h:"endpointها، جدول‌ها، routeها",p:["یک تاپیک می‌تواند به‌جای متن یک جدول نشان دهد: endpointهای HTTP یک پروژه، جدول‌های دیتابیسش، یا routeهایش. snapshot این‌ها را از خود کد می‌خواند، برای هر فریم‌ورک با یک خواننده‌ی کوچک: کنترلرهای NestJS، اپ‌ها و routerهای Express، Minimal APIهای ASP.NET Core؛ اسکریپت‌های SQL، model snapshotهای EF Core و schemaهای Mongoose؛ routeهای Angular، React و Vue. این‌ها عبارت‌های منظم‌اند نه parser، و برای همان شکلی نوشته شده‌اند که این repoها واقعاً کدشان را می‌نویسند.","بهای regular expressionها صداقت درباره‌ی پوشش است: routeی که به سبکی نوشته شده که reader نمی‌شناسد فقط از جدول جا می‌افتد، هرگز ساخته نمی‌شود. یک بخش می‌تواند جدول را با `only` به چند area یا جدول محدود کند، و check‌ی topicها وقتی اسمی آن‌جا در snapshot نباشد شکست می‌خورد، پس controller یا جدولی که اسمش عوض شده به‌صورت شکست دیده می‌شود نه یک جدول خالی."]},{id:"vue",h:"routeهای خود همین سایت",p:["جدول routeها در «سه تب و router» از خواننده‌ی Vue می‌آید: صفحه‌ی یک route، صفحه‌ای که وقتی لازم شود بار می‌شود، یا یک redirect. خواننده‌ی ASP.NET نشان می‌دهد یکی از این‌ها تا کجا می‌رود: گروه‌ها و پیشوندهایشان، بعد policy هر endpoint، از خط خودش یا در غیر این صورت از گروهش."],examples:["vue","aspnet"]}],examples:{vue:{title:{en:"The Vue Router reader",fa:"خواننده‌ی Vue Router"},lang:"javascript",file:"scripts/project-code.mjs",from:"// Vue Router: { path: '...', component: Page }",lines:13},aspnet:{title:{en:"An endpoint's policy",fa:"policy یک endpoint"},lang:"javascript",file:"scripts/project-code.mjs",from:"// The endpoint's own policy is on its last line",lines:6}},quiz:[{q:{en:"Why are the endpoint, table and route tables read from the code rather than written in the topic?",fa:"چرا جدول‌های endpoint، جدول دیتابیس و route از کد خوانده می‌شوند نه این‌که در topic نوشته شوند؟"},options:{en:["They change when the code does, and can never disagree with it","Writing them would break the bilingual check","The scanners are faster than typing"],fa:["با تغییر کد عوض می‌شوند، و هرگز با آن مخالف نیستند","نوشتنشان check‌ی دوزبانه را خراب می‌کرد","scannerها از تایپ کردن سریع‌ترند"]},answer:0,why:{en:"A hand-written table would go stale at the first new endpoint.",fa:"جدول دست‌نویس با اولین endpoint تازه کهنه می‌شد."}},{q:{en:'A section asks for `only: ["Ledger"]` but the controller was renamed. What happens?',fa:'بخشی `only: ["Ledger"]` می‌خواهد ولی اسم controller عوض شده. چه می‌شود؟'},options:{en:["An empty table is shown","The topics check fails: the name is not in the code snapshot","Every endpoint is shown"],fa:["یک جدول خالی نشان داده می‌شود","check‌ی topicها شکست می‌خورد: آن اسم در snapshot کد نیست","همه‌ی endpointها نشان داده می‌شوند"]},answer:1,why:{en:"The check compares every `only` name with the areas and tables in the snapshot.",fa:"check هر اسم `only` را با areaها و جدول‌های snapshot مقایسه می‌کند."}},{q:{en:"What is the trade-off of readers written as regular expressions?",fa:"بده‌بستان readerهایی که با regular expression نوشته شده‌اند چیست؟"},options:{en:["They can run only in the browser","They invent rows for code they don't understand","They are simple, but code written in a style they don't know is left out of the table"],fa:["فقط در مرورگر اجرا می‌شوند","برای کدی که نمی‌فهمند ردیف می‌سازند","ساده‌اند، ولی کدی که به سبکی ناآشنا نوشته شده از جدول بیرون می‌ماند"]},answer:2,why:{en:"They are written against how these repos actually write their code, not as general parsers.",fa:"در برابر شیوه‌ای نوشته شده‌اند که همین repoها واقعاً کد می‌نویسند، نه به‌عنوان parser عمومی."}}]},{id:"bilingual",group:"projects",title:{en:"Two languages, kept in step",fa:"دو زبان، هم‌گام"},files:["src/projects/i18n.ts","scripts/check-projects.mjs"],en:[{id:"strings",h:"The compiler refuses a missing string",p:["The Projects tab is Persian and English from the start. Every interface string is written in both, and the Persian object is typed as the English one, so a key that one language lacks is a type error, not an empty label. The language is part of the address (`#/projects/fa/...`), so a link keeps it; the page's direction follows it.","The reader's choice is also kept in the browser under `projects-lang`, which is where `/projects` alone looks; when storage is blocked the default is Persian."],examples:["head"]},{id:"sections",h:"The same sections in both",p:["`check-projects.mjs` holds every page to the same rule: the Persian and English sections have the same ids in the same order, and show the same examples and the same tables. Prose may differ; what a reader sees beside it may not."],examples:["same"]},{id:"inline",h:"Code and bold, nothing else",p:["Paragraphs are plain text with two marks: backticks for code (always left-to-right, even inside Persian) and double asterisks for bold. Everything else is escaped before the two are turned into HTML.",'The order matters: the five characters that mean something in HTML are replaced by numeric entities first, and only then are the backticks and asterisks turned into tags. So a topic that writes `<script>` shows those characters as text, and a typo in a mark can at worst leave a stray asterisk, never broken markup. Code is marked `dir="ltr"` so that a path or an identifier inside a Persian sentence keeps its order.'],examples:["inline"]}],fa:[{id:"strings",h:"کامپایلر رشته‌ی جاافتاده را رد می‌کند",p:["تب پروژه‌ها از اول فارسی و انگلیسی است. هر رشته‌ی رابط کاربری به هر دو زبان نوشته شده و شیء فارسی با نوع شیء انگلیسی تعریف شده، پس کلیدی که یکی از دو زبان ندارد خطای نوع است، نه یک برچسب خالی. زبان بخشی از آدرس است (`#/projects/fa/...`)، پس لینک آن را نگه می‌دارد؛ جهت صفحه هم دنبال آن می‌رود.","انتخاب خواننده در مرورگر هم زیر `projects-lang` نگه داشته می‌شود، همان جایی که `/projects` به‌تنهایی نگاه می‌کند؛ وقتی storage بسته باشد پیش‌فرض فارسی است."],examples:["head"]},{id:"sections",h:"همان بخش‌ها در هر دو",p:["`check-projects.mjs` همه‌ی صفحه‌ها را به یک قاعده نگه می‌دارد: بخش‌های فارسی و انگلیسی idهای یکسان به ترتیب یکسان دارند و همان مثال‌ها و همان جدول‌ها را نشان می‌دهند. متن می‌تواند فرق کند؛ چیزی که خواننده کنارش می‌بیند نه."],examples:["same"]},{id:"inline",h:"کد و پررنگ، و نه چیز دیگر",p:["پاراگراف‌ها متن ساده با دو علامت‌اند: backtick برای کد (همیشه چپ‌به‌راست، حتی وسط فارسی) و دو ستاره برای پررنگ. هر چیز دیگری قبل از این‌که این دو به HTML تبدیل شوند escape می‌شود.",'ترتیب مهم است: پنج نویسه‌ای که در HTML معنایی دارند اول با entityهای عددی جایگزین می‌شوند، و فقط بعد backtickها و ستاره‌ها به تگ تبدیل می‌شوند. پس topicی که `<script>` بنویسد همان نویسه‌ها را به‌صورت متن نشان می‌دهد، و غلط تایپی در یک علامت در بدترین حالت یک ستاره‌ی اضافه باقی می‌گذارد، هرگز markup شکسته. کد با `dir="ltr"` علامت می‌خورد تا یک مسیر یا شناسه درون جمله‌ی فارسی ترتیبش را نگه دارد.'],examples:["inline"]}],examples:{head:{title:{en:"Both languages, one type",fa:"هر دو زبان، یک نوع"},lang:"typescript",file:"src/projects/i18n.ts",from:"// The Projects tab is bilingual from the start",lines:4},same:{title:{en:"Same ids, same examples, same tables",fa:"همان idها، همان مثال‌ها، همان جدول‌ها"},lang:"javascript",file:"scripts/check-projects.mjs",from:"if (fa.map((s) => s.id).join() !== en.map((s) => s.id).join()) at(`${where}: fa and en sections differ`)",lines:6},inline:{title:{en:"Escape first, then two marks",fa:"اول escape، بعد دو علامت"},lang:"typescript",file:"src/projects/i18n.ts",from:"export function inline(",lines:4}},quiz:[{q:{en:"A new interface string is added to the English object only. What happens?",fa:"یک رشته‌ی رابط تازه فقط به شیء انگلیسی اضافه می‌شود. چه می‌شود؟"},options:{en:["The Persian page shows an empty label","The Persian page shows the English text","The build fails with a type error, since the Persian object is typed as the English one"],fa:["صفحه‌ی فارسی برچسب خالی نشان می‌دهد","صفحه‌ی فارسی متن انگلیسی را نشان می‌دهد","build با خطای نوع شکست می‌خورد، چون شیء فارسی هم‌نوع شیء انگلیسی تعریف شده"]},answer:2,why:{en:"The compiler refuses the missing key, so no reader ever meets the gap.",fa:"کامپایلر کلید جاافتاده را رد می‌کند، پس هیچ خواننده‌ای به آن جای خالی برنمی‌خورد."}},{q:{en:"A topic paragraph contains `<b>` typed as text. How is it shown?",fa:"یک پاراگراف topic شامل `<b>` به‌صورت متن است. چطور نشان داده می‌شود؟"},options:{en:["As the characters `<b>`, because everything is escaped before the two marks become HTML","As bold text","The check refuses it"],fa:["به‌صورت نویسه‌های `<b>`، چون همه چیز پیش از تبدیل دو علامت به HTML escape می‌شود","به‌صورت متن bold","check ردش می‌کند"]},answer:0,why:{en:"Only backticks and double asterisks become tags.",fa:"فقط backtickها و ستاره‌های دوتایی تگ می‌شوند."}},{q:{en:"The Persian and English versions of a section use different wording. Is that allowed?",fa:"نسخه‌ی فارسی و انگلیسی یک بخش متن متفاوتی دارند. مجاز است؟"},options:{en:["No, they must be word-for-word translations","Yes, as long as both have the same section ids in the same order and show the same examples and tables","Only if the English is shorter"],fa:["نه، باید ترجمه‌ی کلمه به کلمه باشند","بله، به شرطی که هر دو همان idهای بخش را به همان ترتیب داشته باشند و همان مثال‌ها و جدول‌ها را نشان دهند","فقط اگر انگلیسی کوتاه‌تر باشد"]},answer:1,why:{en:"Prose may differ; what a reader sees beside it may not.",fa:"متن می‌تواند فرق کند؛ آن‌چه خواننده کنارش می‌بیند نه."}}]},{id:"docs",group:"projects",title:{en:"The docs shell and the map drawing",fa:"قاب مستندات و رسم نقشه"},files:["src/views/projects/ProjectsView.vue","src/projects/model.ts","src/projects/layout.ts","src/components/projects/SystemMap.vue"],en:[{id:"order",h:"Pages in the order a visitor meets them",p:["Every page sits in one list: the system map, then projects grouped by where they run (on the server, on the PC only, outside compose, infrastructure), each followed by its topics, then the styling page. The sidebar, previous and next all come from that one list."],examples:["pages"]},{id:"fold",h:"A sidebar that folds",p:["The project you are in opens in the sidebar to show its topics. Clicking it again folds them, the next click opens them, and going to another project opens that one. On a phone the whole list folds into a menu that closes after a page is picked."],examples:["fold"]},{id:"layout",h:"A layout without a library",p:["The diagrams are SVG laid out by fifty lines of TypeScript: a node's column is the longest path to it, and within a column nodes follow the average row of what points at them, which keeps most arrows short and uncrossed. Arrows always run left to right, whatever the page's direction.",'The map is drawn inside a figure set to `dir="ltr"`, which is why its arrows don\'t flip on the Persian page. An arrow that stays in its column or points back bends out past the right edge instead of cutting through the boxes.'],examples:["layout","edge"]}],fa:[{id:"order",h:"صفحه‌ها به ترتیبی که بازدیدکننده می‌بیند",p:["همه‌ی صفحه‌ها در یک فهرست‌اند: نقشه‌ی سیستم، بعد پروژه‌ها بر اساس جای اجرایشان (روی سرور، فقط روی PC، بیرون از compose، زیرساخت)، هر کدام با تاپیک‌هایش پشت سرش، و بعد صفحه‌ی استایل. نوار کناری، قبلی و بعدی همه از همین یک فهرست می‌آیند."],examples:["pages"]},{id:"fold",h:"نوار کناری‌ای که جمع می‌شود",p:["پروژه‌ای که در آن هستی در نوار کناری باز می‌شود و تاپیک‌هایش را نشان می‌دهد. کلیک دوباره رویش آن‌ها را جمع می‌کند، کلیک بعدی بازشان می‌کند، و رفتن به پروژه‌ی دیگر همان را باز می‌کند. روی گوشی کل فهرست در یک منو جمع می‌شود که بعد از انتخاب صفحه بسته می‌شود."],examples:["fold"]},{id:"layout",h:"چیدمان بدون کتابخانه",p:["نمودارها SVG هستند و پنجاه خط TypeScript آن‌ها را می‌چیند: ستون هر گره بلندترین مسیر تا آن است، و داخل هر ستون گره‌ها دنبال میانگین ردیف گره‌هایی می‌روند که به آن‌ها اشاره می‌کنند، که بیشتر فلش‌ها را کوتاه و بدون تقاطع نگه می‌دارد. فلش‌ها همیشه چپ به راست‌اند، جهت صفحه هر چه باشد.",'نقشه درون figureی با `dir="ltr"` کشیده می‌شود، به همین دلیل پیکان‌هایش در صفحه‌ی فارسی برعکس نمی‌شوند. پیکانی که در ستون خودش می‌ماند یا به عقب برمی‌گردد به جای بریدن از میان جعبه‌ها از لبه‌ی راست بیرون خم می‌شود.'],examples:["layout","edge"]}],examples:{pages:{title:{en:"One list of pages",fa:"یک فهرست صفحه"},lang:"typescript",file:"src/projects/model.ts",from:"export const PAGES: Page[] = [",lines:14},fold:{title:{en:"Open, fold, open",fa:"باز، جمع، باز"},lang:"typescript",file:"src/views/projects/ProjectsView.vue",from:"// Clicking the open project again",lines:8},layout:{title:{en:"Columns by longest path",fa:"ستون‌ها بر اساس بلندترین مسیر"},lang:"typescript",file:"src/projects/layout.ts",from:"// Longest path from the sources",lines:13},edge:{title:{en:"Forward curves, and bends for the rest",fa:"منحنی رو به جلو، و خم برای بقیه"},lang:"typescript",file:"src/projects/layout.ts",from:"export function edgePath(",lines:13}},quiz:[{q:{en:"How is a node's column chosen in the map's layout?",fa:"ستون هر گره در چیدمان نقشه چطور انتخاب می‌شود؟"},options:{en:["Alphabetically","By the longest path to it from a node nothing points at","By the number of its arrows"],fa:["به ترتیب الفبا","با طولانی‌ترین مسیر به آن از گره‌ای که هیچ چیز به آن اشاره نمی‌کند","با تعداد پیکان‌هایش"]},answer:1,why:{en:"That way every arrow that can point forward does; edges that would close a cycle are skipped.",fa:"به این شکل هر پیکانی که بتواند رو به جلو باشد هست؛ یال‌هایی که چرخه می‌ساختند نادیده گرفته می‌شوند."}},{q:{en:"Why do the sidebar and the previous/next links never disagree?",fa:"چرا نوار کناری و لینک‌های قبلی و بعدی هیچ‌وقت با هم ناهماهنگ نیستند؟"},options:{en:["They are tested against each other","The sidebar is generated from the pager","Both come from one list of every page"],fa:["در برابر هم تست می‌شوند","نوار کناری از روی pager ساخته می‌شود","هر دو از یک فهرست از همه‌ی صفحه‌ها می‌آیند"]},answer:2,why:{en:"One ordered list is the single source for both.",fa:"یک فهرست مرتب تنها منبع هر دوست."}},{q:{en:'Why does the map\'s figure set `dir="ltr"`?',fa:'چرا figure‌ی نقشه `dir="ltr"` دارد؟'},options:{en:["So arrows run left to right whatever the page's direction","SVG doesn't support RTL","To make the labels English"],fa:["تا پیکان‌ها، جهت صفحه هر چه باشد، از چپ به راست بروند","SVG از RTL پشتیبانی نمی‌کند","تا برچسب‌ها انگلیسی شوند"]},answer:0,why:{en:"The layout computes x from the left; a flipped figure would mirror the flow.",fa:"چیدمان x را از چپ حساب می‌کند؛ figure‌ی برعکس جریان را آینه‌ای می‌کرد."}}]},{id:"contrast",group:"styling",title:{en:"A build that refuses unreadable colours",fa:"buildی که رنگ ناخوانا را رد می‌کند"},files:["src/styles/abstracts/_tokens.scss","src/styles/abstracts/_functions.scss","src/styles/base/_theme.scss","src/styles/projects/_accents.scss",".stylelintrc.json"],en:[{id:"tokens",h:"Every colour has a name",p:["Raw colours live in one file, `_tokens.scss`; stylelint refuses a hex value anywhere else. The light theme is written in full and the dark one says only what differs. Sass turns both into CSS variables and the browser switches them, since the theme changes after Sass is gone.","stylelint also refuses named colours like `red` and the deprecated `@import`, so a colour can't slip in by another spelling. Paper has its own map of colours, black on white with syntax colours dark enough to print, used only inside the print styles."]},{id:"pairs",h:"Contrast checked at build time",p:["Every pair of text and background colour is listed with its minimum, WCAG AA's 4.5:1 for body text, and Sass computes the ratio in both themes. One pair below its minimum stops the build with the pair's name. Each project's accent is checked the same way, as an outline at 3:1 and under text at 4.5:1. The page “How this site is styled” goes through the rest of the Sass.","The list covers more than body text: the muted grey on both backgrounds, the warning and info boxes, and every highlight.js colour on the code background. Because the check runs inside Sass, a colour that fails never reaches a browser, and the error says which theme and which pair."],examples:["pairs","require","list"]}],fa:[{id:"tokens",h:"هر رنگ یک اسم دارد",p:["رنگ‌های خام در یک فایل‌اند، `_tokens.scss`؛ stylelint مقدار hex را هر جای دیگری رد می‌کند. تم روشن کامل نوشته شده و تم تیره فقط تفاوت‌ها را می‌گوید. Sass هر دو را به متغیرهای CSS تبدیل می‌کند و مرورگر بینشان جابه‌جا می‌شود، چون تم بعد از رفتن Sass عوض می‌شود.","stylelint رنگ‌های نام‌دار مثل `red` و `@import` منسوخ‌شده را هم رد می‌کند، پس هیچ رنگی با املای دیگری راه پیدا نمی‌کند. کاغذ نقشه‌ی رنگ خودش را دارد، سیاه روی سفید با رنگ‌های کد به اندازه‌ی کافی تیره برای چاپ، که فقط در استایل‌های چاپ به کار می‌رود."]},{id:"pairs",h:"contrast موقع build چک می‌شود",p:["هر جفت رنگ متن و پس‌زمینه با حداقلش فهرست شده، 4.5:1 در WCAG AA برای متن، و Sass نسبت را در هر دو تم حساب می‌کند. یک جفت زیر حداقلش build را با اسم همان جفت متوقف می‌کند. رنگ هر پروژه هم همین‌طور چک می‌شود، به‌عنوان خط دور با 3:1 و زیر متن با 4.5:1. صفحه‌ی «استایل این سایت» بقیه‌ی Sass را توضیح می‌دهد.","فهرست بیشتر از متن اصلی را پوشش می‌دهد: خاکستری کم‌رنگ روی هر دو پس‌زمینه، جعبه‌های هشدار و اطلاعات، و هر رنگ highlight.js روی پس‌زمینه‌ی کد. چون چک داخل Sass اجرا می‌شود، رنگی که رد شود هرگز به مرورگر نمی‌رسد، و خطا می‌گوید کدام theme و کدام جفت."],examples:["pairs","require","list"]}],examples:{pairs:{title:{en:"Checked in every theme",fa:"چک‌شده در هر تم"},lang:"scss",file:"src/styles/base/_theme.scss",from:"// Every pair in tokens.$contrast-pairs",lines:6},require:{title:{en:"Too close stops the build",fa:"نزدیک بودن build را متوقف می‌کند"},lang:"scss",file:"src/styles/abstracts/_functions.scss",from:"// Stops the build when two colours",lines:10},list:{title:{en:"The pairs and their minimums",fa:"جفت‌ها و حداقل‌هایشان"},lang:"scss",file:"src/styles/abstracts/_tokens.scss",from:"$contrast-pairs: (",lines:17}},quiz:[{q:{en:"Someone writes `color: #777` in a component's stylesheet. What happens?",fa:"کسی در stylesheet یک کامپوننت `color: #777` می‌نویسد. چه می‌شود؟"},options:{en:["It works, but only in light mode","Sass converts it to a token","stylelint refuses it: raw colours live only in `_tokens.scss`"],fa:["کار می‌کند، ولی فقط در حالت روشن","Sass آن را به یک token تبدیل می‌کند","stylelint ردش می‌کند: رنگ خام فقط در `_tokens.scss` است"]},answer:2,why:{en:"A colour outside the tokens would also escape the contrast check.",fa:"رنگ بیرون از tokenها از چک کنتراست هم فرار می‌کرد."}},{q:{en:"Why are the themes switched by CSS variables rather than by Sass?",fa:"چرا themeها با متغیرهای CSS عوض می‌شوند نه با Sass؟"},options:{en:["Sass can't compute colours","The theme changes in the browser, after Sass has finished","CSS variables are faster"],fa:["Sass نمی‌تواند رنگ حساب کند","theme در مرورگر عوض می‌شود، بعد از این‌که کار Sass تمام شده","متغیرهای CSS سریع‌ترند"]},answer:1,why:{en:"Sass checks both themes at build time and emits both as variables.",fa:"Sass هر دو theme را موقع build چک می‌کند و هر دو را به‌صورت متغیر بیرون می‌دهد."}},{q:{en:"A project's accent passes 3:1 as an outline. Is that enough?",fa:"accent‌ی یک پروژه به‌عنوان خط دور ۳ به ۱ را رد می‌کند. کافی است؟"},options:{en:["No: text on its tinted box must also reach 4.5:1, in both themes","Yes, accents are only graphics","Only the dark theme matters"],fa:["نه: متن روی جعبه‌ی رنگی آن هم باید به ۴٫۵ به ۱ برسد، در هر دو theme","بله، accentها فقط گرافیک‌اند","فقط theme‌ی تیره مهم است"]},answer:0,why:{en:"The box colour is mixed from the accent, so it is checked with the ink and muted text on it.",fa:"رنگ جعبه از accent ترکیب می‌شود، پس با متن اصلی و کم‌رنگ روی آن چک می‌شود."}}]},{id:"ci",group:"deploy",title:{en:"Verify, then deploy",fa:"اول تأیید، بعد استقرار"},files:[".github/workflows/deploy-pages.yml"],en:[{id:"jobs",h:"Nothing is published if a test fails",p:["Every push to `main` runs seven jobs side by side: Python, TypeScript, C#, Java, the frontends, the Docker stack, the ops scripts. The deploy job needs all seven. It then runs `npm run check` and stylelint, builds the site with the repository's name as its base, and prints the booklets.","The deploy job is pinned to Ubuntu 24.04 because Playwright's `--with-deps` needs a release it knows. Before printing, it starts `vite preview` in the background and polls it with curl for up to thirty seconds, so the PDFs are never printed against a server that isn't listening yet."],examples:["deploy"]},{id:"pages",h:"Published to gh-pages",p:["`dist` goes to the `gh-pages` branch as a single fresh commit, with `.nojekyll` so GitHub serves files as they are, and GitHub Pages serves that branch. A newer push cancels a run still in progress.","The workflow asks only for `contents: write`, which pushing the branch needs. `force_orphan` makes each publish a branch with one commit, so `gh-pages` never grows a history of old builds. The newest push wins because all runs share the concurrency group `pages`."],examples:["publish","concurrency"]}],fa:[{id:"jobs",h:"اگر تستی شکست بخورد چیزی منتشر نمی‌شود",p:["هر push به `main` هفت job را کنار هم اجرا می‌کند: Python، TypeScript، C#، Java، فرانت‌اندها، استک Docker، اسکریپت‌های عملیات. job استقرار به هر هفت تا وابسته است. بعد `npm run check` و stylelint را اجرا می‌کند، سایت را با اسم repo به‌عنوان base می‌سازد و جزوه‌ها را چاپ می‌کند.","job‌ی deploy روی Ubuntu 24.04 ثابت شده چون `--with-deps` در Playwright نسخه‌ای را لازم دارد که بشناسد. پیش از چاپ، `vite preview` را در پس‌زمینه بالا می‌آورد و تا سی ثانیه با curl سراغش می‌رود، پس PDFها هیچ‌وقت در برابر سروری که هنوز گوش نمی‌دهد چاپ نمی‌شوند."],examples:["deploy"]},{id:"pages",h:"منتشر در gh-pages",p:["`dist` به‌صورت یک commit تازه‌ی تنها به branch `gh-pages` می‌رود، با `.nojekyll` تا GitHub فایل‌ها را همان‌طور که هستند سرو کند، و GitHub Pages همان branch را سرو می‌کند. push جدیدتر اجرایی را که هنوز تمام نشده لغو می‌کند.","workflow فقط `contents: write` را می‌خواهد، که push کردن شاخه لازمش دارد. `force_orphan` هر انتشار را شاخه‌ای با یک commit می‌کند، پس `gh-pages` هیچ‌وقت تاریخچه‌ای از buildهای قدیمی جمع نمی‌کند. جدیدترین push برنده است چون همه‌ی اجراها در گروه concurrency‌ی `pages` شریک‌اند."],examples:["publish","concurrency"]}],examples:{deploy:{title:{en:"The deploy job",fa:"job استقرار"},lang:"yaml",file:".github/workflows/deploy-pages.yml",from:"needs: [python, typescript, csharp, java, frontend, docker, ops]",to:"SITE_URL=http://localhost:4173/"},publish:{title:{en:"dist to gh-pages",fa:"dist به gh-pages"},lang:"yaml",file:".github/workflows/deploy-pages.yml",from:"- run: touch dist/.nojekyll",lines:7},concurrency:{title:{en:"One run at a time",fa:"یک اجرا در هر لحظه"},lang:"yaml",file:".github/workflows/deploy-pages.yml",from:"concurrency:",lines:3}},quiz:[{q:{en:"The Docker job fails but the six others pass. What is published?",fa:"job‌ی Docker شکست می‌خورد ولی شش تای دیگر قبول می‌شوند. چه منتشر می‌شود؟"},options:{en:["The site without the Docker lessons","Nothing: the deploy job needs all seven","Everything, with a warning"],fa:["سایت بدون درس‌های Docker","هیچ: job‌ی deploy هر هفت تا را لازم دارد","همه چیز، با یک هشدار"]},answer:1,why:{en:"`needs` lists every test job, so one failure skips the deploy.",fa:"`needs` همه‌ی jobهای تست را فهرست می‌کند، پس یک شکست deploy را رد می‌کند."}},{q:{en:"Why is `.nojekyll` added to `dist`?",fa:"چرا `.nojekyll` به `dist` اضافه می‌شود؟"},options:{en:["So GitHub serves the files as they are, without running Jekyll on them","To disable caching","It is required by Vite"],fa:["تا GitHub فایل‌ها را همان‌طور که هستند سرو کند، بدون اجرای Jekyll روی آن‌ها","تا caching غیرفعال شود","Vite لازمش دارد"]},answer:0,why:{en:"Jekyll would, for one, skip files and folders whose names start with an underscore.",fa:"Jekyll، از جمله، فایل‌ها و پوشه‌هایی را که اسمشان با زیرخط شروع می‌شود رد می‌کرد."}},{q:{en:"Two pushes land a minute apart. What happens to the first run?",fa:"دو push با یک دقیقه فاصله می‌رسند. برای اجرای اول چه می‌شود؟"},options:{en:["It finishes, then the second runs","Both publish, in any order","It is cancelled, since both share the concurrency group `pages`"],fa:["تمام می‌شود، بعد دومی اجرا می‌شود","هر دو منتشر می‌کنند، به هر ترتیبی","لغو می‌شود، چون هر دو در گروه concurrency‌ی `pages` شریک‌اند"]},answer:2,why:{en:"`cancel-in-progress` means an older build can never overwrite a newer one.",fa:"`cancel-in-progress` یعنی build قدیمی‌تر هرگز نمی‌تواند روی جدیدتر بنویسد."}}]},{id:"vps",group:"deploy",title:{en:"On the VPS: code.arashkeshtgar.ca",fa:"روی VPS: ‏code.arashkeshtgar.ca"},files:["src/lib/booklets.ts","vite.config.ts","src/router/index.ts"],en:[{id:"build",h:"Built by Control Panel",p:["This repo has no Dockerfile of its own. On the VPS, Control Panel's compose builds the `programming-web` service from this folder with `deploy/programming/web.Dockerfile`: `npm ci` without Playwright's browser, `npm run build` with `VITE_PDF_BASE` pointing at the PDFs on GitHub Pages, then nginx serving `dist`. Caddy puts code.arashkeshtgar.ca in front of it, public.","Control Panel's `deploy.sh` pulls this repo with the others and rebuilds what changed, so a push here reaches the VPS at the next deploy, not on its own.","The Dockerfile skips Playwright's browser download, since printing happens only in CI, and the PDF address is a build argument defaulting to the GitHub Pages copy. Compose binds the container to `127.0.0.1` only, so the one way in from outside is through Caddy, and a healthcheck fetches `/` every thirty seconds."],examples:["pdfbase"]},{id:"plain",h:"Why plain nginx is enough",p:["The site is static and its routes live in the hash, so the server never sees `/lesson/l002`: it only ever serves `index.html` and the assets. There is no fallback rule to write, and none to get wrong."],examples:["hash"]}],fa:[{id:"build",h:"build شده به دست کنترل پنل",p:["این repo هیچ Dockerfile مخصوص خودش ندارد. روی VPS، compose کنترل پنل سرویس `programming-web` را از همین پوشه با `deploy/programming/web.Dockerfile` می‌سازد: `npm ci` بدون مرورگر Playwright، `npm run build` با `VITE_PDF_BASE` که به PDFهای GitHub Pages اشاره می‌کند، و بعد nginx که `dist` را سرو می‌کند. Caddy دامنه‌ی code.arashkeshtgar.ca را به‌صورت عمومی جلوی آن می‌گذارد.","`deploy.sh` کنترل پنل این repo را همراه بقیه pull می‌کند و هر چه عوض شده را دوباره می‌سازد، پس push این‌جا در deploy بعدی به VPS می‌رسد، نه خودبه‌خود.","Dockerfile دانلود مرورگر Playwright را رد می‌کند، چون چاپ فقط در CI انجام می‌شود، و آدرس PDFها یک build argument است با پیش‌فرض نسخه‌ی GitHub Pages. compose container را فقط به `127.0.0.1` وصل می‌کند، پس تنها راه ورود از بیرون از طریق Caddy است، و یک healthcheck هر سی ثانیه `/` را می‌گیرد."],examples:["pdfbase"]},{id:"plain",h:"چرا nginx ساده کافی است",p:["سایت ایستاست و routeهایش در hash هستند، پس سرور هیچ‌وقت `/lesson/l002` را نمی‌بیند: فقط `index.html` و فایل‌های assets را سرو می‌کند. قاعده‌ی fallbackی نیست که نوشته شود، و نه که اشتباه نوشته شود."],examples:["hash"]}],examples:{pdfbase:{title:{en:"Links to the PDFs on Pages",fa:"لینک به PDFهای روی Pages"},lang:"typescript",file:"src/lib/booklets.ts",from:"// Where the booklet PDFs live.",lines:3},hash:{title:{en:"Hash history",fa:"hash history"},lang:"typescript",file:"src/router/index.ts",from:"// Hash history keeps deep links working",lines:3}},quiz:[{q:{en:"Why does the VPS need no SPA fallback rule in nginx?",fa:"چرا VPS به قانون fallback‌ی SPA در nginx نیاز ندارد؟"},options:{en:["nginx adds one by default","Caddy rewrites the paths","The routes live in the hash, so the server only ever serves `index.html` and the assets"],fa:["nginx به‌طور پیش‌فرض یکی اضافه می‌کند","Caddy مسیرها را بازنویسی می‌کند","routeها در hash‌اند، پس سرور همیشه فقط `index.html` و assetها را سرو می‌کند"]},answer:2,why:{en:"The server never sees `/lesson/l002`, so there is nothing to fall back from.",fa:"سرور هیچ‌وقت `/lesson/l002` را نمی‌بیند، پس چیزی برای fallback نیست."}},{q:{en:"You push a lesson fix to this repo. When does code.arashkeshtgar.ca show it?",fa:"اصلاح یک درس را به این repo push می‌کنید. code.arashkeshtgar.ca کی آن را نشان می‌دهد؟"},options:{en:["At once, through a webhook","At Control Panel's next deploy, which pulls this repo and rebuilds what changed","After the PDFs are printed on the VPS"],fa:["فوراً، از راه یک webhook","در deploy بعدی Control Panel، که این repo را pull می‌کند و آن‌چه عوض شده را دوباره می‌سازد","بعد از چاپ PDFها روی VPS"]},answer:1,why:{en:"GitHub Pages updates on its own; the VPS waits for a deploy.",fa:"GitHub Pages خودش به‌روز می‌شود؛ VPS منتظر یک deploy می‌ماند."}}]}],n={project:e,repo:s,scan:t,groups:a,pages:o};export{n as default,a as groups,o as pages,e as project,s as repo,t as scan};
